const NetworkActivityVisualizer: React.FC = () => {
    const canvasRef = useRef<HTMLCanvasElement>(null);

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        let w = 300, h = 300;
        let time = 0;
        let frameId: number;

        const nodes = Array.from({length: 12}, () => ({
            x: Math.random() * 100, y: Math.random() * 100,
            vx: (Math.random()-0.5)*0.2, vy: (Math.random()-0.5)*0.2
        }));

        const render = () => {
            time += 0.01;
            if (canvas.parentElement) {
                w = canvas.parentElement.clientWidth;
                h = canvas.parentElement.clientHeight;
                canvas.width = w; canvas.height = h;
            }
            ctx.fillStyle = '#0c0c0e';
            ctx.fillRect(0,0,w,h);

            // Draw Grid
            ctx.strokeStyle = '#222';
            ctx.lineWidth = 1;
            ctx.beginPath();
            for(let x=0; x<=w; x+=30) { ctx.moveTo(x,0); ctx.lineTo(x,h); }
            for(let y=0; y<=h; y+=30) { ctx.moveTo(0,y); ctx.lineTo(w,y); }
            ctx.stroke();

            // Draw Nodes & Links
            nodes.forEach((n, i) => {
                n.x += n.vx; n.y += n.vy;
                if(n.x<0||n.x>100) n.vx*=-1; if(n.y<0||n.y>100) n.vy*=-1;

                const px = (n.x/100)*w;
                const py = (n.y/100)*h;

                // Draw connections
                nodes.forEach((n2, j) => {
                    if (i === j) return;
                    const px2 = (n2.x/100)*w;
                    const py2 = (n2.y/100)*h;
                    const dist = Math.hypot(px-px2, py-py2);
                    if (dist < 100) {
                        ctx.strokeStyle = `rgba(6, 182, 212, ${1 - dist/100})`;
                        ctx.beginPath(); ctx.moveTo(px,py); ctx.lineTo(px2,py2); ctx.stroke();
                    }
                });

                ctx.fillStyle = '#06b6d4';
                ctx.beginPath(); ctx.arc(px, py, 3, 0, Math.PI*2); ctx.fill();
            });

            frameId = requestAnimationFrame(render);
        };
        render();
        return () => cancelAnimationFrame(frameId);
    }, []);

    return (
        <div className="my-16 group cursor-default w-full aspect-square transition-all duration-1000 transform">
            <div className="w-full h-full bg-[#0c0c0e] border border-white/10 rounded-lg relative overflow-hidden shadow-2xl">
                <canvas ref={canvasRef} className="absolute inset-0 w-full h-full" />
                <div className="absolute bottom-4 left-4 text-[9px] font-mono text-cyan-400 uppercase tracking-widest bg-black/50 px-2 py-1 rounded border border-cyan-500/20">
                    Live Network Activity
                </div>
            </div>
        </div>
    );
};

