                            <div className={`text-[9px] font-bold uppercase tracking-widest mb-2 opacity-50 flex items-center gap-2 ${msg.role === 'user' ? 'text-black/50' : 'text-white/50'}`}>
                                {msg.role === 'user' ? "You (Manager)" : scenario.bridge.agentName}
