                    </div>
                ))}
            </div>

            {/* Options */}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-3 pt-4 border-t border-white/10">
                {scenario.bridge.options.map((opt: any, i: number) => (
                    <button 
                        key={i}
                        onClick={() => handleOption(opt)}
