    const nextStep = () => setStep(prev => Math.min(prev + 1, scenario.reason.steps.length));

    return (
        <div className="h-full flex flex-col p-8 bg-[#0c0c0e] justify-center items-center">
            <div className="w-full max-w-xl space-y-8">

                {/* Header */}
