                        <BrainCircuit size={14} className="animate-pulse" /> Chain of Thought
                    </div>
                    <div className="text-white/30 text-xs font-mono">
                        Step {step} / {scenario.reason.steps.length}
                    </div>
                </div>

                {/* Steps */}
                <div className="space-y-4">
