const InputTerminal = ({ active, scenario }: { active: boolean, scenario: any }) => {
    const [messages, setMessages] = useState<any[]>([]);
    const [inputValue, setInputValue] = useState("");
    const scrollRef = useRef<HTMLDivElement>(null);
    const hasInitialized = useRef(false);

    // Initial Sequence
    useEffect(() => {
        if (!active) {
            setMessages([]);
            hasInitialized.current = false;
            return;
        }
        if (hasInitialized.current) return;
        hasInitialized.current = true;

        // Simulate scanning logs
        scenario.locate.logs.forEach((log: any, i: number) => {
            setTimeout(() => {
                setMessages(prev => [...prev, log]);
            }, i * 600 + 200);
        });

    }, [active, scenario]);

    // Auto-scroll
    useEffect(() => {
        if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }, [messages]);

    const handleSend = (e?: React.FormEvent) => {
        e?.preventDefault();
        if (!inputValue.trim()) return;

        const text = inputValue;
        setInputValue("");
        setMessages(prev => [...prev, { type: 'user', text }]);

        setTimeout(() => {
            setMessages(prev => [...prev, { type: 'typing' }]);
            setTimeout(() => {
                setMessages(prev => {
                    const filtered = prev.filter(m => m.type !== 'typing');
