// --- 2. STREAM (Terminal / Logs) ---
const StreamInterface = ({ active }: { active: boolean }) => {
    const [lines, setLines] = useState<string[]>([]);
    const scrollRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        if (!active) {
            setLines([]);
            return;
        }

        const logs = [
            "INFO: Connecting to Sector_4_Data_Lake...",
            "SUCCESS: Connection established (Latency: 12ms)",
            "STREAM: Ingesting real-time telemetry from Node A...",
            "WARN: Timestamp drift detected in packet #44291",
            "ACTION: Normalizing timestamp formats [-2ms adjustment]",
            "STREAM: Shadowing workflow ID: 99-Alpha...",
            "DETECT: Regulatory constraint found in payload",
            "MATCH: GDPR Article 32 - Encryption Required",
            "ACTION: Tagging payload as 'HIGH_SENSITIVITY'",
            "STREAM: Consolidating policy drift...",
            "SUCCESS: Stream buffered. Agents ready."
        ];

        let i = 0;
        const interval = setInterval(() => {
            if (i < logs.length) {
                setLines(prev => [...prev, logs[i]]);
                i++;
            } else {
                clearInterval(interval);
            }
        }, 400);

        return () => clearInterval(interval);
    }, [active]);

    useEffect(() => {
        if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }, [lines]);

    return (
        <div className="w-full h-full bg-[#0c0c0e] font-mono text-xs md:text-sm p-4 flex flex-col">
            <div className="flex items-center justify-between mb-4 border-b border-white/10 pb-2">
                <div className="flex gap-2 text-white/50">
                    <Terminal size={14} />
                    <span>agent-stream-v1</span>
                </div>
                <div className="flex gap-4">
                    <span className="text-[#69B7B2]">● Live</span>
                    <span className="text-white/30">CPU: 12%</span>
                </div>
            </div>

            <div ref={scrollRef} className="flex-1 overflow-y-auto space-y-2 text-white/70">
                {lines.map((line, i) => (
                    <div key={i} className="animate-in slide-in-from-left-2 fade-in duration-300">
                        <span className="text-white/20 mr-4">
                            {new Date().toLocaleTimeString()}
                        </span>
                        <span className={
                            line.includes("WARN") ? "text-amber-400" :
                            line.includes("SUCCESS") ? "text-green-400" :
                            line.includes("ACTION") ? "text-[#69B7B2]" :
                            line.includes("DETECT") ? "text-purple-400" : "text-white"
                        }>
                            {line}
                        </span>
                    </div>
                ))}
                <div className="w-2 h-4 bg-[#69B7B2] animate-pulse inline-block align-middle ml-1" />
            </div>
        </div>
    );
};

// --- 3. CONTEXT (VS Code / JSON Builder) ---
const ContextInterface = ({ active }: { active: boolean }) => {
    const [rawText, setRawText] = useState("");
    const [jsonContent, setJsonContent] = useState<any>({});
    const [highlight, setHighlight] = useState(false);

    useEffect(() => {
        if (!active) {
            setRawText("");
            setJsonContent({});
            setHighlight(false);
            return;
        }

        const source = "Observed raw data flow from external vendor. Attributing 'GDPR' framework to data subset. Risk threshold exceeded.";

        // Typewriter effect for Raw Text
        let i = 0;
        const typeInterval = setInterval(() => {
            setRawText(source.substring(0, i));
            i++;
            if (i > source.length) {
                clearInterval(typeInterval);
                setHighlight(true);

                // Build JSON step-by-step
                setTimeout(() => setJsonContent(prev => ({ ...prev, observation: "External Vendor Flow" })), 500);
                setTimeout(() => setJsonContent(prev => ({ ...prev, framework: "GDPR" })), 1000);
                setTimeout(() => setJsonContent(prev => ({ ...prev, risk_level: "CRITICAL" })), 1500);
                setTimeout(() => setJsonContent(prev => ({ ...prev, action: "Encryption Mandated" })), 2000);
            }
        }, 30);

        return () => clearInterval(typeInterval);
    }, [active]);

    return (
        <div className="w-full h-full bg-[#1e1e1e] flex text-sm font-mono">
            {/* Sidebar */}
            <div className="w-12 border-r border-white/5 flex flex-col items-center py-4 gap-4 text-white/40">
                <FileText size={20} className="text-white" />
                <Search size={20} />
                <Network size={20} />
            </div>

            {/* Editor Area */}
            <div className="flex-1 flex">
                {/* Left: Raw Input */}
                <div className="flex-1 p-4 border-r border-white/5 relative">
                    <div className="text-xs text-white/30 mb-4 uppercase tracking-widest">Input: Unstructured</div>
                    <div className="text-white/60 leading-relaxed whitespace-pre-wrap relative">
                        {rawText}
                        {highlight && <span className="absolute inset-0 bg-[#69B7B2]/20 animate-pulse" />}
                    </div>
                </div>

                {/* Right: Structured Output */}
                <div className="flex-1 p-4 bg-[#1a1a1a]">
