            setCursor({ x: 50, y: 30 });
            await new Promise(r => setTimeout(r, 600));
            setScanProgress(p => ({ ...p, '2': 40 })); // Start scanning folder

            // Move to critical file
            setCursor({ x: 20, y: 60 });
            await new Promise(r => setTimeout(r, 500));
            setScanProgress(p => ({ ...p, '4': 100 }));

            // Scan rest rapidly
            setTimeout(() => setScanProgress(prev => ({...prev, '2': 100})), 1000);
            setTimeout(() => setScanProgress(prev => ({...prev, '3': 100})), 1500);
            setTimeout(() => setScanProgress(prev => ({...prev, '5': 100})), 1800);
            setTimeout(() => setScanProgress(prev => ({...prev, '6': 100})), 2000);
        };

        sequence();
    }, [active]);

    return (
        <div className="w-full h-full bg-[#1a1a1c] text-gray-300 font-sans flex flex-col relative overflow-hidden">
            <Cursor x={cursor.x} y={cursor.y} label="Indexing..." />

