const StreamInterface = ({ active }: { active: boolean }) => {
    const [lines, setLines] = useState<string[]>([]);
    const scrollRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        if (!active) {
            setLines([]);
            return;
        }

        const logs = [
            "INFO: Connecting to Sector_4_Data_Lake...",
            "SUCCESS: Connection established (Latency: 12ms)",
            "STREAM: Ingesting real-time telemetry from Node A...",
            "WARN: Timestamp drift detected in packet #44291",
            "ACTION: Normalizing timestamp formats [-2ms adjustment]",
            "STREAM: Shadowing workflow ID: 99-Alpha...",
            "DETECT: Regulatory constraint found in payload",
            "MATCH: GDPR Article 32 - Encryption Required",
            "ACTION: Tagging payload as 'HIGH_SENSITIVITY'",
            "STREAM: Consolidating policy drift...",
            "SUCCESS: Stream buffered. Agents ready."
        ];

        let i = 0;
        const interval = setInterval(() => {
            if (i < logs.length) {
                setLines(prev => [...prev, logs[i]]);
                i++;
            } else {
                clearInterval(interval);
            }
        }, 400);

        return () => clearInterval(interval);
    }, [active]);

    useEffect(() => {
        if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }, [lines]);

    return (
        <div className="w-full h-full bg-[#0c0c0e] font-mono text-xs md:text-sm p-4 flex flex-col">
            <div className="flex items-center justify-between mb-4 border-b border-white/10 pb-2">
                <div className="flex gap-2 text-white/50">
                    <Terminal size={14} />
                    <span>agent-stream-v1</span>
                </div>
                <div className="flex gap-4">
                    <span className="text-[#69B7B2]">● Live</span>
                    <span className="text-white/30">CPU: 12%</span>
                </div>
            </div>

            <div ref={scrollRef} className="flex-1 overflow-y-auto space-y-2 text-white/70">
                {lines.map((line, i) => (
                    <div key={i} className="animate-in slide-in-from-left-2 fade-in duration-300">
                        <span className="text-white/20 mr-4">
                            {new Date().toLocaleTimeString()}
                        </span>
                        <span className={
                            line.includes("WARN") ? "text-amber-400" :
                            line.includes("SUCCESS") ? "text-green-400" :
                            line.includes("ACTION") ? "text-[#69B7B2]" :
                            line.includes("DETECT") ? "text-purple-400" : "text-white"
