const ContextInterface = ({ active }: { active: boolean }) => {
    const [rawText, setRawText] = useState("");
    const [jsonContent, setJsonContent] = useState<any>({});
    const [highlight, setHighlight] = useState(false);

    useEffect(() => {
        if (!active) {
            setRawText("");
            setJsonContent({});
            setHighlight(false);
            return;
        }

        const source = "Observed raw data flow from external vendor. Attributing 'GDPR' framework to data subset. Risk threshold exceeded.";

        // Typewriter effect for Raw Text
        let i = 0;
        const typeInterval = setInterval(() => {
            setRawText(source.substring(0, i));
            i++;
            if (i > source.length) {
                clearInterval(typeInterval);
                setHighlight(true);

                // Build JSON step-by-step
                setTimeout(() => setJsonContent(prev => ({ ...prev, observation: "External Vendor Flow" })), 500);
                setTimeout(() => setJsonContent(prev => ({ ...prev, framework: "GDPR" })), 1000);
                setTimeout(() => setJsonContent(prev => ({ ...prev, risk_level: "CRITICAL" })), 1500);
                setTimeout(() => setJsonContent(prev => ({ ...prev, action: "Encryption Mandated" })), 2000);
            }
        }, 30);

        return () => clearInterval(typeInterval);
    }, [active]);

    return (
        <div className="w-full h-full bg-[#1e1e1e] flex text-sm font-mono">
            {/* Sidebar */}
            <div className="w-12 border-r border-white/5 flex flex-col items-center py-4 gap-4 text-white/40">
                <FileText size={20} className="text-white" />
                <Search size={20} />
                <Network size={20} />
            </div>

            {/* Editor Area */}
            <div className="flex-1 flex">
                {/* Left: Raw Input */}
                <div className="flex-1 p-4 border-r border-white/5 relative">
                    <div className="text-xs text-white/30 mb-4 uppercase tracking-widest">Input: Unstructured</div>
                    <div className="text-white/60 leading-relaxed whitespace-pre-wrap relative">
                        {rawText}
                        {highlight && <span className="absolute inset-0 bg-[#69B7B2]/20 animate-pulse" />}
                    </div>
                </div>

                {/* Right: Structured Output */}
                <div className="flex-1 p-4 bg-[#1a1a1a]">
