const GovernanceInterface = ({ active }: { active: boolean }) => {
    interface TaskItem {
        id: string;
        title: string;
        tag: string;
        priority: string;
    }

    const [columns, setColumns] = useState<{
        todo: TaskItem[];
        processing: TaskItem[];
        done: TaskItem[];
    }>({
        todo: [
            { id: '1', title: 'Encrypt External Flows', tag: 'SecOps', priority: 'High' },
            { id: '2', title: 'Audit Log Retention', tag: 'Compliance', priority: 'Med' }
        ],
        processing: [],
        done: []
    });

    useEffect(() => {
        if (!active) return; // Reset logic could go here

        const moveCard = async () => {
            // Wait
            await new Promise(r => setTimeout(r, 1000));

            // Move "Encrypt" to Processing
            setColumns(prev => {
                if (prev.todo.length === 0) return prev;
                return {
                    todo: [prev.todo[1]],
                    processing: [prev.todo[0]],
                    done: []
                };
            });

            await new Promise(r => setTimeout(r, 1500));

            // Move to Done
            setColumns(prev => {
                if (prev.processing.length === 0) return prev;
                return {
                    todo: prev.todo,
                    processing: [],
                    done: [prev.processing[0]]
                };
            });
        };

        moveCard();
    }, [active]);

    return (
        <div className="w-full h-full bg-[#151517] p-6 font-sans">
            <div className="flex justify-between items-center mb-6">
                <h2 className="text-white font-bold text-sm flex items-center gap-2">
