                            {col} <span className="ml-2 bg-white/5 px-1.5 rounded text-white/50">
                                {i === 0 ? columns.todo.length : i === 1 ? columns.processing.length : columns.done.length}
                            </span>
                        </div>
                        <div className="space-y-2">
                            {i === 0 && columns.todo.map(c => <GovernanceCard key={c.id} item={c} />)}
                            {i === 1 && columns.processing.map(c => <GovernanceCard key={c.id} item={c} />)}
