const ContextInterface = ({ active }: { active: boolean }) => {
    const [rawText, setRawText] = useState("");
    const [jsonContent, setJsonContent] = useState<any>({});
    const [highlight, setHighlight] = useState(false);

    useEffect(() => {
        if (!active) {
            setRawText("");
            setJsonContent({});
            setHighlight(false);
            return;
        }

        const source = "Observed raw data flow from external vendor. Attributing 'GDPR' framework to data subset. Risk threshold exceeded.";

        let i = 0;
        const typeInterval = setInterval(() => {
            setRawText(source.substring(0, i));
            i++;
            if (i > source.length) {
                clearInterval(typeInterval);
                setHighlight(true);

                // Build JSON step-by-step
                setTimeout(() => setJsonContent(prev => ({ ...prev, observation: "External Vendor Flow" })), 500);
                setTimeout(() => setJsonContent(prev => ({ ...prev, framework: "GDPR" })), 1000);
                setTimeout(() => setJsonContent(prev => ({ ...prev, risk_level: "CRITICAL" })), 1500);
                setTimeout(() => setJsonContent(prev => ({ ...prev, action: "Encryption Mandated" })), 2000);
            }
        }, 30);

        return () => clearInterval(typeInterval);
    }, [active]);

    // Simple syntax highlighter for JSON
    const renderJSON = (data: any) => {
        if (Object.keys(data).length === 0) return <span className="text-white/20">Waiting for context...</span>;

        return (
            <div className="font-mono text-xs">
                <span className="text-yellow-400">{'{'}</span>
                {Object.entries(data).map(([key, value], idx) => (
                    <div key={key} className="pl-4">
                        <span className="text-sky-300">"{key}"</span>: <span className="text-orange-300">"{value}"</span>
                        {idx < Object.keys(data).length - 1 && <span className="text-white/50">,</span>}
                    </div>
                ))}
                <span className="text-yellow-400">{'}'}</span>
            </div>
        );
    };

    return (
        <div className="w-full h-full bg-[#1e1e1e] flex text-sm font-mono overflow-hidden">
            {/* Sidebar */}
            <div className="w-10 border-r border-white/5 flex flex-col items-center py-4 gap-4 text-white/40 bg-[#252526]">
