        ],
        processing: [],
        done: []
    });

    useEffect(() => {
        if (!active) return; // Reset logic could go here

        const moveCard = async () => {
            // Wait
            await new Promise(r => setTimeout(r, 1000));

            // Move "Encrypt" to Processing
