const DriveInterface = ({ active }: { active: boolean }) => {
    const [scanProgress, setScanProgress] = useState<Record<string, number>>({});
    const [cursor, setCursor] = useState({ x: 50, y: 50 });
    const [storageUsed, setStorageUsed] = useState(45);

    const files = [
        { id: '1', name: 'Q3_Financials.xlsx', type: 'sheet', owner: 'Finance', modified: '2m ago' },
        { id: '2', name: 'Vendor_Contracts', type: 'folder', owner: 'Legal', modified: '1h ago' },
        { id: '3', name: 'Patient_Records_Dump', type: 'folder', owner: 'Clinical', modified: 'Yesterday' },
        { id: '4', name: 'Site_Safety_Protocol.pdf', type: 'pdf', owner: 'Ops', modified: 'Oct 24' },
        { id: '5', name: 'Email_Archive_2024.zip', type: 'zip', owner: 'IT', modified: 'Sep 12' },
        { id: '6', name: 'Board_Deck_Final.pptx', type: 'ppt', owner: 'Exec', modified: 'Aug 01' },
    ];

    useEffect(() => {
        if (!active) {
            setScanProgress({});
            return;
        }

        const sequence = async () => {
            // Move cursor to first file
            setCursor({ x: 20, y: 35 });
            await new Promise(r => setTimeout(r, 800));
            setScanProgress(p => ({ ...p, '1': 100 })); // Instant scan
            setStorageUsed(prev => prev + 0.1);

            // Move to folder
            setCursor({ x: 50, y: 35 });
            await new Promise(r => setTimeout(r, 600));
            setScanProgress(p => ({ ...p, '2': 40 })); // Start scanning folder

            // Move to critical file
            setCursor({ x: 20, y: 60 });
            await new Promise(r => setTimeout(r, 500));
            setScanProgress(p => ({ ...p, '4': 100 }));
            setStorageUsed(prev => prev + 0.2);

            // Scan rest rapidly
            setTimeout(() => { setScanProgress(prev => ({...prev, '2': 100})); setStorageUsed(p=>p+1.5); }, 1000);
            setTimeout(() => { setScanProgress(prev => ({...prev, '3': 100})); setStorageUsed(p=>p+12.0); }, 1500);
            setTimeout(() => { setScanProgress(prev => ({...prev, '5': 100})); setStorageUsed(p=>p+5.2); }, 1800);
            setTimeout(() => { setScanProgress(prev => ({...prev, '6': 100})); setStorageUsed(p=>p+0.5); }, 2000);
        };

        sequence();
    }, [active]);

    return (
        <div className="w-full h-full bg-[#1a1a1c] text-gray-300 font-sans flex flex-col relative overflow-hidden text-xs">
            <Cursor x={cursor.x} y={cursor.y} label="Indexing..." />

            {/* Toolbar */}
            <div className="h-14 border-b border-white/5 flex items-center px-4 justify-between bg-[#202124]">
                <div className="flex items-center gap-4 w-full max-w-xl">
                    <span className="text-lg font-medium text-white tracking-tight flex items-center gap-2">
                        <img src="https://upload.wikimedia.org/wikipedia/commons/1/12/Google_Drive_icon_%282020%29.svg" className="w-6 h-6 grayscale opacity-80" alt=""/> 
                        Drive
                    </span>
                    <div className="flex-1 bg-[#303134] rounded-lg h-9 flex items-center px-4 gap-2 text-gray-400">
                        <Search size={14} />
                        <span>Search in Drive</span>
                        <div className="ml-auto flex gap-2">
                            <Filter size={14} />
                        </div>
                    </div>
                </div>
                <div className="flex gap-4 opacity-50">
                    <Grid size={18} />
                    <Clock size={18} />
                </div>
            </div>

            {/* Sidebar + Content */}
            <div className="flex-1 flex">
                <div className="w-48 border-r border-white/5 p-3 space-y-4 hidden md:flex flex-col">
                    <div className="flex items-center gap-3 px-4 py-2.5 bg-[#303134] hover:bg-[#3c4043] transition-colors rounded-2xl text-white font-medium w-max shadow-md cursor-pointer">
                        <span className="text-xl leading-none">+</span> New
                    </div>
                    <div className="space-y-0.5 text-[11px] font-medium">
                        <div className="px-3 py-1.5 bg-[#69B7B2]/20 text-[#69B7B2] rounded-r-full font-bold flex gap-2"><Folder size={14} fill="currentColor" /> My Drive</div>
                        <div className="px-3 py-1.5 opacity-60 hover:bg-white/5 rounded-r-full flex gap-2 cursor-pointer"><Users size={14} /> Shared drives</div>
                        <div className="px-3 py-1.5 opacity-60 hover:bg-white/5 rounded-r-full flex gap-2 cursor-pointer"><Share2 size={14} /> Shared with me</div>
                        <div className="px-3 py-1.5 opacity-60 hover:bg-white/5 rounded-r-full flex gap-2 cursor-pointer"><Clock size={14} /> Recent</div>
                    </div>

                    <div className="mt-auto px-2">
                        <div className="h-1 w-full bg-white/10 rounded-full overflow-hidden mb-2">
                            <div className="h-full bg-blue-400 transition-all duration-500" style={{ width: `${Math.min(100, storageUsed)}%` }} />
