                        <span className="hover:bg-white/5 px-2 py-1 rounded cursor-pointer">Q3_Uploads</span>
                    </div>

                    <div className="text-[11px] font-medium mb-3 text-white/60">Suggested</div>
                    <div className="grid grid-cols-2 md:grid-cols-3 gap-3">
                        {files.map(f => {
                            const scanned = scanProgress[f.id] === 100;
                            const scanning = scanProgress[f.id] > 0 && scanProgress[f.id] < 100;

                            return (
                                <div key={f.id} className="relative group bg-[#303134] rounded-xl p-3 border border-white/5 hover:border-white/20 hover:bg-[#3c4043] transition-all overflow-hidden shadow-sm hover:shadow-md cursor-pointer">
