                                    {(scanning || scanned) && (
                                        <div className={`absolute inset-0 bg-[#69B7B2]/10 z-10 flex items-center justify-center backdrop-blur-[1px] transition-opacity ${scanned ? 'opacity-0' : 'opacity-100'}`}>
