                                         <FileText className="text-blue-400" size={18} />}
                                        <div className="text-xs font-medium text-white truncate">{f.name}</div>
                                    </div>
                                    <div className="h-16 bg-black/20 rounded-lg mb-2 overflow-hidden relative">
                                        <div className="absolute inset-0 opacity-20 bg-white" style={{ width: scanned ? '100%' : '30%' }} />
                                    </div>
                                    <div className="flex items-center justify-between text-[9px] text-gray-400">
                                        <div className="flex items-center gap-1.5">
                                            <div className="w-3.5 h-3.5 rounded-full bg-purple-500/20 text-purple-300 flex items-center justify-center font-bold text-[8px]">{f.owner[0]}</div>
                                            {f.owner}
                                        </div>
                                        <span>{f.modified}</span>
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                </div>
            </div>
        </div>
    );
