const StreamInterface = ({ active }: { active: boolean }) => {
    const [lines, setLines] = useState<string[]>([]);
    const [dataRate, setDataRate] = useState(0);
    const scrollRef = useRef<HTMLDivElement>(null);

    // Fake Sparkline Data
    const [sparkline, setSparkline] = useState<number[]>(new Array(20).fill(5));

    useEffect(() => {
        if (!active) {
            setLines([]);
            setSparkline(new Array(20).fill(5));
            return;
        }

        const logs = [
            "INFO: Connecting to Sector_4_Data_Lake...",
            "SUCCESS: Connection established (Latency: 12ms)",
            "STREAM: Ingesting real-time telemetry from Node A...",
            "WARN: Timestamp drift detected in packet #44291",
            "ACTION: Normalizing timestamp formats [-2ms adjustment]",
            "STREAM: Shadowing workflow ID: 99-Alpha...",
            "DETECT: Regulatory constraint found in payload",
            "MATCH: GDPR Article 32 - Encryption Required",
            "ACTION: Tagging payload as 'HIGH_SENSITIVITY'",
            "STREAM: Consolidating policy drift...",
            "SUCCESS: Stream buffered. Agents ready."
        ];

        let i = 0;
        const interval = setInterval(() => {
            if (i < logs.length) {
                setLines(prev => [...prev, logs[i]]);
                // Random sparkline update
                setDataRate(Math.floor(Math.random() * 500) + 1200);
                setSparkline(prev => [...prev.slice(1), Math.random() * 20]);
                i++;
            } else {
                clearInterval(interval);
            }
        }, 400);

        return () => clearInterval(interval);
    }, [active]);

    useEffect(() => {
        if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }, [lines]);

    return (
        <div className="w-full h-full bg-[#0c0c0e] font-mono text-xs md:text-sm p-4 flex flex-col border border-white/5 rounded-b-xl">
            {/* Terminal Header */}
            <div className="flex items-center justify-between mb-4 border-b border-white/10 pb-2">
                <div className="flex gap-3 text-white/50 items-center">
                    <Terminal size={14} />
                    <span className="font-bold text-white/80">agent-stream-v1</span>
                    <span className="bg-white/10 px-1.5 py-0.5 rounded text-[9px] text-white/40">bash</span>
                </div>
                <div className="flex gap-4 items-center">
                    <div className="flex items-end gap-1 h-4 w-16">
                        {sparkline.map((val, i) => (
                            <div key={i} className="w-1 bg-[#69B7B2]" style={{ height: `${val + 2}px` }} />
                        ))}
                    </div>
                    <span className="text-[#69B7B2] text-[10px]">{dataRate} kb/s</span>
                </div>
            </div>

            <div ref={scrollRef} className="flex-1 overflow-y-auto space-y-1.5 text-white/70 font-mono text-[11px] leading-relaxed">
                {lines.map((line, i) => (
                    <div key={i} className="animate-in slide-in-from-left-2 fade-in duration-300 flex">
                        <span className="text-white/20 mr-4 w-16 shrink-0 text-right select-none">
                            {new Date().toLocaleTimeString([], { hour12: false })}
                        </span>
                        <span className={
                            line.includes("WARN") ? "text-amber-400" :
                            line.includes("SUCCESS") ? "text-green-400" :
                            line.includes("ACTION") ? "text-[#69B7B2]" :
                            line.includes("DETECT") ? "text-purple-400" : "text-white"
                        }>
                            {line}
