        if (!active) {
            setRawText("");
            setJsonContent({});
            setHighlight(false);
            return;
        }

        const source = "Observed raw data flow from external vendor. Attributing 'GDPR' framework to data subset. Risk threshold exceeded.";

        let i = 0;
        const typeInterval = setInterval(() => {
            setRawText(source.substring(0, i));
            i++;
            if (i > source.length) {
                clearInterval(typeInterval);
                setHighlight(true);

                // Build JSON step-by-step
                setTimeout(() => setJsonContent(prev => ({ ...prev, observation: "External Vendor Flow" })), 500);
                setTimeout(() => setJsonContent(prev => ({ ...prev, framework: "GDPR" })), 1000);
                setTimeout(() => setJsonContent(prev => ({ ...prev, risk_level: "CRITICAL" })), 1500);
                setTimeout(() => setJsonContent(prev => ({ ...prev, action: "Encryption Mandated" })), 2000);
            }
        }, 30);

        return () => clearInterval(typeInterval);
    }, [active]);

    // Simple syntax highlighter for JSON
    const renderJSON = (data: any) => {
        if (Object.keys(data).length === 0) return <span className="text-white/20">Waiting for context...</span>;

        return (
            <div className="font-mono text-xs">
                <span className="text-yellow-400">{'{'}</span>
                {Object.entries(data).map(([key, value], idx) => (
                    <div key={key} className="pl-4">
                        <span className="text-sky-300">"{key}"</span>: <span className="text-orange-300">"{value}"</span>
                        {idx < Object.keys(data).length - 1 && <span className="text-white/50">,</span>}
                    </div>
                ))}
                <span className="text-yellow-400">{'}'}</span>
            </div>
        );
    };

    return (
        <div className="w-full h-full bg-[#1e1e1e] flex text-sm font-mono overflow-hidden">
            {/* Sidebar */}
            <div className="w-10 border-r border-white/5 flex flex-col items-center py-4 gap-4 text-white/40 bg-[#252526]">
                <FileText size={18} className="text-white" />
                <Search size={18} />
                <Network size={18} />
            </div>

            {/* Editor Area */}
            <div className="flex-1 flex flex-col md:flex-row">
                {/* Left: Raw Input */}
                <div className="flex-1 border-r border-white/5 relative flex flex-col">
                    <div className="bg-[#2d2d2d] px-4 py-2 text-[10px] uppercase text-white/50 font-bold flex justify-between">
                        <span>input.txt</span>
                        <span className="opacity-50">UTF-8</span>
                    </div>
                    <div className="flex-1 p-4 relative">
                        <div className="text-white/60 leading-relaxed whitespace-pre-wrap relative z-10">
                            {rawText}
                        </div>
                        {highlight && <div className="absolute inset-0 bg-[#69B7B2]/10 animate-pulse pointer-events-none" />}
                    </div>
                </div>

                {/* Right: Structured Output */}
                <div className="flex-1 bg-[#1e1e1e] flex flex-col">
                    <div className="bg-[#2d2d2d] px-4 py-2 text-[10px] uppercase text-[#69B7B2] font-bold flex justify-between border-l border-white/5">
                        <span className="flex items-center gap-2"><Bot size={10}/> output.json</span>
                        {highlight && <span className="animate-pulse">Processing...</span>}
                    </div>

                    <div className="flex-1 flex">
                        {/* Line Numbers */}
                        <div className="w-8 bg-[#1e1e1e] text-right pr-2 pt-4 text-[10px] text-white/20 select-none border-r border-white/5 font-mono leading-relaxed">
                            <div>1</div><div>2</div><div>3</div><div>4</div><div>5</div><div>6</div>
                        </div>

                        {/* Content */}
                        <div className="p-4 flex-1">
                            {renderJSON(jsonContent)}
