            return;
        }

        const sequence = async () => {
            // Simulate agent "Locating" sources
            setCursor({ x: 20, y: 35 });
            await new Promise(r => setTimeout(r, 600));
            setScanProgress(p => ({ ...p, '1': 100 })); 
            setStorageUsed(prev => prev + 0.1);

            setCursor({ x: 50, y: 35 });
            await new Promise(r => setTimeout(r, 500));
            setScanProgress(p => ({ ...p, '2': 40 })); 

            setCursor({ x: 80, y: 35 });
            await new Promise(r => setTimeout(r, 500));
            setScanProgress(p => ({ ...p, '3': 60 }));

            // Rapid scan rest
            setTimeout(() => { setScanProgress(prev => ({...prev, '2': 100})); setStorageUsed(p=>p+1.5); }, 1000);
            setTimeout(() => { setScanProgress(prev => ({...prev, '3': 100})); setStorageUsed(p=>p+12.0); }, 1500);
            setTimeout(() => { setScanProgress(prev => ({...prev, '5': 100})); setStorageUsed(p=>p+5.2); }, 1800);
        };

        sequence();
    }, [active]);

    return (
        <div className="w-full h-full bg-[#1a1a1c] text-gray-300 font-sans flex flex-col relative overflow-hidden text-xs">
            <Cursor x={cursor.x} y={cursor.y} label="Identifying Sources..." />

            {/* Toolbar */}
            <div className="h-14 border-b border-white/5 flex items-center px-4 justify-between bg-[#202124]">
                <div className="flex items-center gap-4 w-full max-w-xl">
                    <span className="text-lg font-medium text-white tracking-tight flex items-center gap-2">
                        <Globe size={18} className="text-[#69B7B2]" />
                        Source Map
                    </span>
                    <div className="flex-1 bg-[#303134] rounded-lg h-9 flex items-center px-4 gap-2 text-gray-400 font-mono text-[10px]">
                        <Search size={14} />
                        <span>Searching internal & external networks...</span>
                    </div>
                </div>
            </div>

            {/* Sidebar + Content */}
            <div className="flex-1 flex">
                <div className="w-48 border-r border-white/5 p-3 space-y-4 hidden md:flex flex-col bg-[#151517]">
                    <div className="text-[10px] font-bold uppercase tracking-widest text-white/30 pl-2">Landscape</div>
                    <div className="space-y-0.5 text-[11px] font-medium">
                        <div className="px-3 py-1.5 bg-[#69B7B2]/10 text-[#69B7B2] rounded border-l-2 border-[#69B7B2] flex gap-2"><Network size={14} /> All Sources</div>
                        <div className="px-3 py-1.5 opacity-60 hover:bg-white/5 rounded flex gap-2"><Database size={14} /> Databases</div>
                        <div className="px-3 py-1.5 opacity-60 hover:bg-white/5 rounded flex gap-2"><Cloud size={14} /> External APIs</div>
                    </div>

                    <div className="mt-auto px-2">
                        <div className="text-[10px] text-white/40 mb-2">Ingestion Bandwidth</div>
                        <div className="h-1 w-full bg-white/10 rounded-full overflow-hidden mb-2">
                            <div className="h-full bg-[#69B7B2] transition-all duration-500" style={{ width: `${Math.min(100, storageUsed)}%` }} />
                        </div>
                    </div>
                </div>

                <div className="flex-1 p-6">
                    <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
                        {sources.map(s => {
                            const scanned = scanProgress[s.id] === 100;
                            const scanning = scanProgress[s.id] > 0 && scanProgress[s.id] < 100;

                            return (
                                <div key={s.id} className="relative group bg-[#252528] rounded-xl p-4 border border-white/5 hover:border-white/20 transition-all overflow-hidden shadow-lg">
                                    {(scanning || scanned) && (
                                        <div className={`absolute inset-0 bg-[#69B7B2]/5 z-10 flex items-center justify-center backdrop-blur-[1px] transition-opacity ${scanned ? 'opacity-0' : 'opacity-100'}`}>
                                            <div className="text-[#69B7B2] font-mono font-bold text-[9px] uppercase tracking-widest animate-pulse">Connecting...</div>
                                        </div>
                                    )}
                                    {scanned && (
                                        <div className="absolute top-2 right-2 text-[#69B7B2] animate-in zoom-in">
                                            <CheckCircle2 size={14} />
