        ],
        active: [],
        encoded: []
    });

    useEffect(() => {
        if (!active) return;

        const moveCard = async () => {
            await new Promise(r => setTimeout(r, 800));
            // Move to Active
            setColumns(prev => {
                if (prev.todo.length === 0) return prev;
                return {
                    todo: [prev.todo[1]],
                    active: [prev.todo[0]],
                    encoded: []
                };
