        }

        const templates = [
            { type: 'invoice', raw: "INV-2921 from Acme Corp ($4,200) - Overdue", color: "text-amber-400" },
            { type: 'email', raw: "Subject: Project Alpha delays - Urgent", color: "text-blue-400" },
            { type: 'log', raw: "Error: Database timeout on cluster us-east-1", color: "text-red-400" },
            { type: 'slack', raw: "@channel deployment failed in staging", color: "text-purple-400" }
        ];

        const interval = setInterval(() => {
            const template = templates[Math.floor(Math.random() * templates.length)];
            const newEvent = {
                id: Date.now(),
                ...template,
                status: 'pending', // pending -> processing -> done
                agent: null
            };

            setEvents(prev => [newEvent, ...prev].slice(0, 6)); // Keep last 6
        }, 1200);

        return () => clearInterval(interval);
    }, [active]);

    // Simulate Agent Processing
    useEffect(() => {
        if (!active) return;

        const processInterval = setInterval(() => {
            setEvents(prev => {
                // Find pending event
                const targetIdx = prev.findIndex(e => e.status === 'pending');
                if (targetIdx === -1) return prev; // Nothing to do

                const next = [...prev];
                // Start processing
                next[targetIdx] = { ...next[targetIdx], status: 'processing', agent: 'Analyzer_Bot' };

                // Finish processing shortly after
                setTimeout(() => {
                    setEvents(curr => {
                        const doneNext = [...curr];
                        const doneIdx = doneNext.findIndex(e => e.id === next[targetIdx].id);
                        if (doneIdx !== -1) {
                            doneNext[doneIdx] = { ...doneNext[doneIdx], status: 'done', agent: null };
                        }
                        return doneNext;
                    });
                }, 800);

                return next;
            });
        }, 1000);

        return () => clearInterval(processInterval);
    }, [active]);

    return (
        <div className="w-full h-full bg-[#0a0a0c] flex flex-col font-mono text-xs overflow-hidden relative">
            {/* Header */}
            <div className="h-10 bg-[#111] border-b border-white/5 flex items-center px-4 gap-4">
                <div className="flex items-center gap-2 text-green-400">
                    <Activity size={12} className="animate-pulse" />
                    <span className="font-bold">LIVE_FEED</span>
                </div>
                <div className="flex-1 h-px bg-white/5" />
                <div className="text-white/30">4 Agents Active</div>
            </div>

            {/* Stream Content */}
            <div className="flex-1 p-4 space-y-3 overflow-hidden">
                {events.map((ev) => (
                    <div key={ev.id} className="relative pl-8 group animate-in slide-in-from-top-2 duration-500">
                        {/* Timeline Line */}
                        <div className="absolute left-3 top-0 bottom-0 w-px bg-white/10 group-last:bg-gradient-to-b group-last:from-white/10 group-last:to-transparent" />

                        {/* Status Dot */}
                        <div className={`absolute left-[9px] top-3 w-1.5 h-1.5 rounded-full transition-colors duration-300 ${
                            ev.status === 'done' ? 'bg-[#69B7B2] shadow-[0_0_8px_#69B7B2]' : 
                            ev.status === 'processing' ? 'bg-amber-400 animate-ping' : 
                            'bg-white/20'
                        }`} />

                        <div className={`relative p-3 rounded border transition-all duration-500 ${
                            ev.status === 'processing' ? 'bg-white/5 border-white/20' : 
                            ev.status === 'done' ? 'bg-[#0f1110] border-[#69B7B2]/20' : 
                            'bg-transparent border-transparent opacity-50'
                        }`}>
                            {/* Agent Cursor Overlay */}
                            {ev.status === 'processing' && (
                                <div className="absolute -right-2 -top-2 flex items-center gap-2 bg-amber-500 text-black px-2 py-0.5 rounded-full text-[9px] font-bold animate-bounce z-10 shadow-lg">
                                    <Bot size={10} /> Processing...
                                </div>
                            )}

                            <div className="flex justify-between items-start mb-1">
                                <span className={`font-bold uppercase tracking-wider ${ev.color}`}>{ev.type}</span>
                                <span className="text-white/20">{new Date(ev.id).toLocaleTimeString([], {hour12: false, minute:'2-digit', second:'2-digit'})}</span>
                            </div>
                            <div className="text-white/80 truncate">{ev.raw}</div>

                            {/* Enrichment Data */}
