                    <button onClick={() => setActiveStage(prev => (prev + 1) % stages.length)} className="text-white/50 hover:text-white flex items-center gap-2 text-xs font-bold uppercase tracking-widest">
                        Next <ArrowRight size={14} />
                    </button>
                </div>

            </div>
        </section>
    );
};

