// --- 5. CONTROL (Knowledge Graph) ---
const ControlApp = ({ active }: { active: boolean }) => {
    const [showIntro, setShowIntro] = useState(true);
    useEffect(() => { if(active) setShowIntro(true); }, [active]);

    const canvasRef = useRef<HTMLCanvasElement>(null);
    const [nodes, setNodes] = useState<{id: number, x: number, y: number, r: number, color: string, label: string}[]>([]);

    // Init Graph
    useEffect(() => {
        const initialNodes = [
            { id: 0, x: 300, y: 300, r: 30, color: '#fff', label: "Shipment #8842" },
            { id: 1, x: 0, y: 0, r: 15, color: '#69B7B2', label: "Supplier: Apex" },
            { id: 2, x: 0, y: 0, r: 15, color: '#f59e0b', label: "Risk: Temp" },
            { id: 3, x: 0, y: 0, r: 15, color: '#69B7B2', label: "Route: JFK" },
            { id: 4, x: 0, y: 0, r: 15, color: '#8b5cf6', label: "PO: #9921" },
            { id: 5, x: 0, y: 0, r: 15, color: '#ef4444', label: "Delay: +4h" },
            { id: 6, x: 0, y: 0, r: 15, color: '#69B7B2', label: "Dest: Austin" },
            { id: 7, x: 0, y: 0, r: 15, color: '#fff', label: "Handler: D. Chen" },
            { id: 8, x: 0, y: 0, r: 15, color: '#f59e0b', label: "Sensor: 4B" }
        ];
        setNodes(initialNodes);
    }, []);

    // Graph Simulation
    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        let frameId: number;
        let time = 0;

        const render = () => {
            time += 0.01;
            const w = canvas.parentElement?.clientWidth || 600;
            const h = canvas.parentElement?.clientHeight || 600;
            canvas.width = w; canvas.height = h;

            const cx = w/2; const cy = h/2;

            ctx.clearRect(0, 0, w, h);

            // Update Nodes (Floating)
            nodes.forEach((n, i) => {
                if (i === 0) { n.x = cx; n.y = cy; return; } // Pin center
                const angle = (i / 8) * Math.PI * 2 + time * 0.1;
                n.x = cx + Math.cos(angle) * 180 + Math.sin(time + i)*10;
                n.y = cy + Math.sin(angle) * 180 + Math.cos(time + i)*10;
            });

            // Draw Connections
            ctx.lineWidth = 1;
            nodes.forEach((n, i) => {
                if (i === 0) return;
                const dist = Math.sqrt((n.x-cx)**2 + (n.y-cy)**2);
                ctx.strokeStyle = `rgba(255,255,255,${0.1 + (1-dist/300)*0.2})`;
                ctx.beginPath();
                ctx.moveTo(cx, cy);
                ctx.lineTo(n.x, n.y);
                ctx.stroke();

                // Data Packet
                const pProgress = (time * 2 + i * 0.5) % 1;
                const px = cx + (n.x - cx) * pProgress;
                const py = cy + (n.y - cy) * pProgress;
                ctx.fillStyle = '#fff';
                ctx.fillRect(px-1.5, py-1.5, 3, 3);
            });

            // Draw Nodes
            nodes.forEach(n => {
                ctx.fillStyle = n.color;
                ctx.beginPath();
                ctx.arc(n.x, n.y, n.r, 0, Math.PI*2);
                ctx.fill();

                // Hover effect simulation (pulse)
                if (Math.random() > 0.98) {
                    ctx.strokeStyle = n.color;
                    ctx.globalAlpha = 0.5;
                    ctx.beginPath(); ctx.arc(n.x, n.y, n.r + 5, 0, Math.PI*2); ctx.stroke();
                    ctx.globalAlpha = 1;
                }

                // Label
                ctx.fillStyle = '#fff';
                ctx.font = '10px sans-serif';
                ctx.textAlign = 'center';
                ctx.fillText(n.label, n.x, n.y + n.r + 15);
            });

            frameId = requestAnimationFrame(render);
        };
        render();
        return () => cancelAnimationFrame(frameId);
    }, [nodes]);

    return (
        <div className="w-full h-full bg-[#050505] relative overflow-hidden flex flex-col">
            {showIntro && (
                <GuideOverlay 
                    title="Supply Chain Graph"
                    description="Mapping the hidden dependencies. See how Shipment #8842 connects to suppliers, risks, and downstream orders."
                    onDismiss={() => setShowIntro(false)} 
                />
            )}

            <div className="absolute top-4 left-4 z-20 bg-[#1a1a1c] border border-white/10 rounded-full px-4 py-2 flex items-center gap-2 shadow-xl">
                <Search size={14} className="text-white/40" />
                <input type="text" placeholder="Search Entity..." className="bg-transparent border-none text-xs text-white focus:outline-none w-32" value="Shipment #8842" readOnly />
            </div>

            <canvas ref={canvasRef} className="w-full h-full block" />

            <div className="absolute bottom-6 right-6 bg-[#1a1a1c]/90 backdrop-blur border border-white/10 p-4 rounded-xl w-48 shadow-2xl">
                <div className="text-[10px] font-bold text-white/40 uppercase tracking-widest mb-3">Graph Stats</div>
                <div className="space-y-2">
                    <div className="flex justify-between text-[10px] text-white/60">
                        <span>Nodes</span>
                        <span className="text-white">9</span>
                    </div>
                    <div className="flex justify-between text-[10px] text-white/60">
                        <span>Risk Score</span>
                        <span className="text-red-400">High</span>
                    </div>
                    <div className="h-1 w-full bg-white/10 rounded-full overflow-hidden mt-2">
                        <div className="h-full w-3/4 bg-[#69B7B2]" />
                    </div>
                </div>
            </div>
        </div>
    );
};

// --- 6. BRIDGE (Chat Assistant) ---
const BridgeApp = ({ active }: { active: boolean }) => {
    const [messages, setMessages] = useState<any[]>([]);
    const [step, setStep] = useState(0);
    const [showIntro, setShowIntro] = useState(true);
    useEffect(() => { if(active) setShowIntro(true); }, [active]);

    // Automation sequence
    useEffect(() => {
        if (!active) {
            setMessages([]);
            setStep(0);
            return;
        }

        const script = [
            { type: 'user', content: 'What is the status of the Project Titan shipment?', delay: 1000 },
            { type: 'system', sources: ['Flexport / #8842', 'Samsara / 4B', 'SAP / PO#9921'], delay: 2000 },
            { type: 'assistant', content: "Shipment #8842 is delayed. **IoT Sensor 4B** reported a temperature excursion (28°C) at 14:00 today. The automated logic has flagged it for QA inspection upon arrival at JFK.", delay: 4000 }
        ];

        let timeouts: ReturnType<typeof setTimeout>[] = [];
        let accumulatedDelay = 0;

        script.forEach((msg, idx) => {
            accumulatedDelay += msg.delay;
            timeouts.push(setTimeout(() => {
                setMessages(prev => [...prev, msg]);
                setStep(idx + 1);
            }, accumulatedDelay));
        });

        // Loop
        const resetTime = accumulatedDelay + 5000;
        const loop = setInterval(() => {
            setMessages([]);
            setStep(0);
            let loopDelay = 0;
            script.forEach((msg) => {
                loopDelay += msg.delay;
                setTimeout(() => {
                    setMessages(prev => [...prev, msg]);
                }, loopDelay);
            });
        }, resetTime);

        return () => {
            timeouts.forEach(clearTimeout);
            clearInterval(loop);
        };
    }, [active]);

    return (
        <div className="flex flex-col h-full bg-[#0a0a0c] font-sans relative overflow-hidden">
