import React, { useEffect, useRef } from 'react';

interface SectionVisualizerProps {
    mode: 'search' | 'redaction' | 'logic' | 'core' | 'shield' | 'swarm' | 'predictive' | 'translation' | 'identity';
    color: string;
}

export const SectionVisualizer: React.FC<SectionVisualizerProps> = ({ mode, color }) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const containerRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const canvas = canvasRef.current;
        const container = containerRef.current;
        if (!canvas || !container) return;

        const ctx = canvas.getContext('2d', { alpha: true });
        if (!ctx) return;

        let frameId: number;
        let time = 0;

        // --- STATE MANAGEMENT ---
        const state: any = {
            width: 0,
            height: 0,
            particles: [],
            nodes: [],
            links: [], 
            grid: [],
            columns: [], 
            task: null, 
            agent: { state: 'idle', t: 0, heldBox: null, armHeight: 0, armExt: 0 },
            boxes: [], 
            stack: [],
            // Identity Mode (Learning Feed) State
            feedState: 'reading', // reading -> selecting -> feedback -> swiping
            feedTimer: 0,
            currentCardIndex: 0,
            swipeOffset: 0,
            streak: 12,
            xp: 450,
            cursor: { x: 0, y: 0, targetX: 0, targetY: 0 },
            feedCards: [
                { type: 'SECURITY', q: "Phishing Suspicion", sub: "Urgent email from 'IT-Support'", opts: ["Click Link", "Report"], correct: 1, color: "#ef4444" },
                { type: 'SAFETY', q: "Forklift Zone", sub: "Pedestrian in yellow lane", opts: ["Right of Way", "Yield"], correct: 1, color: "#f59e0b" },
                { type: 'DATA', q: "PII Detected", sub: "SSN in comments field", opts: ["Redact", "Ignore"], correct: 0, color: "#3b82f6" },
                { type: 'COMPLIANCE', q: "Gift Policy", sub: "Vendor offers $200 tickets", opts: ["Decline", "Accept"], correct: 0, color: "#10b981" },
                { type: 'OPS', q: "Server Load", sub: "CPU at 95% for 5m", opts: ["Wait", "Scale Up"], correct: 1, color: "#8b5cf6" }
            ],
            // Logic/Strategy Mode State
            packets: [],
            initializedMode: null
        };

        const resize = () => {
            const rect = container.getBoundingClientRect();
            const dpr = window.devicePixelRatio || 1;

            canvas.width = rect.width * dpr;
            canvas.height = rect.height * dpr;

            canvas.style.width = `${rect.width}px`;
            canvas.style.height = `${rect.height}px`;

            ctx.scale(dpr, dpr);

            state.width = rect.width;
            state.height = rect.height;

            if (mode !== state.initializedMode) {
                init(rect.width, rect.height);
            }
        };

        const init = (w: number, h: number) => {
            state.particles = [];
            state.nodes = [];
            state.links = [];
            state.grid = [];
            state.columns = [];
            state.task = null;
            state.boxes = [];
            state.stack = [];
            state.packets = [];
            state.agent = { state: 'idle', t: 0, heldBox: null, armHeight: 0, armExt: 0 };

            // Identity specific
            state.feedState = 'reading';
            state.feedTimer = 0;
            state.currentCardIndex = 0;
            state.swipeOffset = 0;
            state.streak = 12;
            state.cursor = { x: w/2, y: h/2, targetX: w/2, targetY: h/2 };

            state.initializedMode = mode;

            if (mode === 'search') {
                const particleCount = 80;
                for(let i=0; i<particleCount; i++) {
                    state.particles.push({
                        x: Math.random() * w,
                        y: Math.random() * h,
                        vx: 2 + Math.random() * 1.5,
                        vy: (Math.random() - 0.5) * 0.5,
                        targetLane: Math.floor(Math.random() * 5),
                        size: 0.5 + Math.random() * 0.5
                    });
                }
            }
            else if (mode === 'redaction') {
                const cols = 8;
                const rows = 12;
                const cw = w / cols;
                const ch = h / rows;
                for(let r=0; r<rows; r++) {
                    for(let c=0; c<cols; c++) {
                        if (Math.random() > 0.4) {
                            state.particles.push({
                                x: c * cw + 5, y: r * ch + 5,
                                w: cw - 10, h: ch - 10,
                                active: false
                            });
                        }
                    }
                }
            }
            else if (mode === 'logic') {
                // STRATEGY BUILDER: Concrete Flowchart Layout
                // Layer 1: Inputs
                state.nodes.push({ id: 0, x: w * 0.15, y: h * 0.3, label: "DEMAND SPIKE", type: 'trigger', active: 0 });
                state.nodes.push({ id: 1, x: w * 0.15, y: h * 0.7, label: "INVENTORY LOW", type: 'trigger', active: 0 });

                // Layer 2: Logic/Process
                state.nodes.push({ id: 2, x: w * 0.45, y: h * 0.5, label: "ALLOCATION LOGIC", type: 'process', active: 0 });

                // Layer 3: Decision/Action
                state.nodes.push({ id: 3, x: w * 0.75, y: h * 0.25, label: "PRIORITY: RETAIL", type: 'action', active: 0 });
                state.nodes.push({ id: 4, x: w * 0.75, y: h * 0.75, label: "LIMIT WHOLESALE", type: 'action', active: 0 });

                // Edges
                state.links.push({ from: 0, to: 2 });
                state.links.push({ from: 1, to: 2 });
                state.links.push({ from: 2, to: 3 });
                state.links.push({ from: 2, to: 4 });
            }
            else if (mode === 'core') {
                // NETWORK INITIALIZATION
                state.nodes.push({ x: 0, y: 0, layer: 0, active: 0, angle: 0, r: 0 });
                const rings = [6, 12, 24]; 
                const radii = [60, 120, 180]; 
                rings.forEach((count, ringIdx) => {
                    const radius = radii[ringIdx];
                    for(let i=0; i<count; i++) {
                        const angle = (i / count) * Math.PI * 2;
                        const offset = (Math.random() - 0.5) * 20;
                        state.nodes.push({
                            x: Math.cos(angle) * (radius + offset),
                            y: Math.sin(angle) * (radius + offset),
                            layer: ringIdx + 1,
                            active: 0,
                            angle: angle,
                            r: radius
                        });
                    }
                });
                for(let i=0; i<state.nodes.length; i++) {
                    const n1 = state.nodes[i];
                    if (n1.layer === 1) {
                        state.links.push({ from: 0, to: i });
                    }
                    if (n1.layer < rings.length) {
                        const nextLayerNodes = state.nodes.map((n: any, idx: number) => ({...n, idx})).filter((n: any) => n.layer === n1.layer + 1);
                        nextLayerNodes.sort((a:any, b:any) => {
                            const d1 = Math.abs(a.angle - n1.angle);
                            const d2 = Math.abs(b.angle - n1.angle);
                            return d1 - d2;
                        });
                        if(nextLayerNodes[0]) state.links.push({ from: i, to: nextLayerNodes[0].idx });
                        if(nextLayerNodes[1]) state.links.push({ from: i, to: nextLayerNodes[1].idx });
                    }
                    const sameLayer = state.nodes.map((n: any, idx: number) => ({...n, idx})).filter((n: any) => n.layer === n1.layer && n.idx !== i);
                    let closest = null; let minD = 100;
                    sameLayer.forEach((n: any) => {
                        let d = Math.abs(n.angle - n1.angle);
                        if (d > Math.PI) d = Math.PI * 2 - d; 
                        if (d < minD) { minD = d; closest = n.idx; }
                    });
                    if (closest !== null && i < closest) state.links.push({ from: i, to: closest });
                }
            }
        };

        const render = () => {
            time += 0.007; // SLOWED DOWN BY 30%
            const w = state.width;
            const h = state.height;
            const cx = w/2;
            const cy = h/2;

            ctx.clearRect(0, 0, w, h);

            // ... (Keeping existing render logic for other modes) ...
            if (mode === 'search') {
                const processLine = w * 0.4;
                const laneCount = 5;
                const laneHeight = h / laneCount;

                ctx.lineWidth = 1;
                ctx.strokeStyle = 'rgba(255, 255, 255, 0.08)';
                for(let i=0; i<laneCount; i++) {
                    const ly = i * laneHeight + laneHeight/2;
                    ctx.beginPath(); ctx.moveTo(processLine, ly); ctx.lineTo(w, ly); ctx.stroke();
                }

                const scannerGlow = ctx.createLinearGradient(processLine, 0, processLine + 60, 0);
                scannerGlow.addColorStop(0, color);
                scannerGlow.addColorStop(1, 'transparent');
                ctx.fillStyle = scannerGlow;
                ctx.globalAlpha = 0.15;
                ctx.fillRect(processLine, 0, 60, h);

                ctx.fillStyle = color;
                ctx.globalAlpha = 0.8;
                ctx.fillRect(processLine, 0, 2, h);

                state.particles.forEach((p: any) => {
                    p.x += p.vx;
                    if (p.x < processLine) {
                        p.y += p.vy;
                        if (p.y < 0) p.y += h;
                        if (p.y > h) p.y -= h;
                        ctx.fillStyle = 'rgba(255, 255, 255, 0.4)';
                        ctx.globalAlpha = 0.6;
                        ctx.beginPath(); ctx.arc(p.x, p.y, p.size * 2, 0, Math.PI*2); ctx.fill();
                    } else {
                        const targetY = p.targetLane * laneHeight + laneHeight/2;
                        p.y += (targetY - p.y) * 0.15; 
                        p.x += 1.5; 
                        ctx.fillStyle = color;
                        ctx.globalAlpha = 1;
                        const packetWidth = 20 * p.size;
                        const packetHeight = 4;
                        ctx.shadowColor = color; ctx.shadowBlur = 10;
                        ctx.fillRect(p.x, p.y - packetHeight/2, packetWidth, packetHeight);
                        ctx.shadowBlur = 0;
                    }
                    if (p.x > w + 50) {
                        p.x = -20;
                        p.y = Math.random() * h;
                        p.vx = 2 + Math.random() * 1.5;
                        p.targetLane = Math.floor(Math.random() * laneCount);
                    }
                });
            }
            else if (mode === 'redaction') {
                const scanY = (time * 100) % (h + 100) - 50;
                state.particles.forEach((p: any) => {
                    const dist = Math.abs(p.y - scanY);
                    if (dist < 50) {
                        ctx.fillStyle = color;
                        ctx.globalAlpha = 1 - (dist/50);
                        ctx.fillRect(p.x, p.y, p.w, p.h);
                    } else {
                        ctx.fillStyle = 'rgba(255,255,255,0.05)';
                        ctx.globalAlpha = 1;
                        ctx.fillRect(p.x, p.y, p.w, p.h);
                    }
                });
                ctx.fillStyle = '#fff';
                ctx.fillRect(0, scanY, w, 2);
            }
            else if (mode === 'logic') {
                // --- STRATEGY BUILDER ---

                // Spawn Packets
                if (Math.random() > 0.98) {
                    const startNodes = state.nodes.filter((n: any) => n.type === 'trigger');
                    const start = startNodes[Math.floor(Math.random() * startNodes.length)];
                    state.nodes.forEach((n: any) => { if(n.id === start.id) n.active = 1.0; });

                    // Find links from this start
                    const links = state.links.filter((l: any) => l.from === start.id);
                    links.forEach((l: any) => {
                        state.packets.push({
                            fromId: l.from, toId: l.to, progress: 0, speed: 0.02 + Math.random() * 0.01
                        });
                    });
                }

                // Draw Links
                ctx.lineWidth = 2;
                state.links.forEach((l: any) => {
                    const n1 = state.nodes.find((n: any) => n.id === l.from);
                    const n2 = state.nodes.find((n: any) => n.id === l.to);

                    const grad = ctx.createLinearGradient(n1.x, n1.y, n2.x, n2.y);
                    grad.addColorStop(0, 'rgba(255,255,255,0.1)');
                    grad.addColorStop(1, 'rgba(255,255,255,0.05)');
                    ctx.strokeStyle = grad;

                    // Elbow connector
                    ctx.beginPath();
                    ctx.moveTo(n1.x, n1.y);
                    const midX = (n1.x + n2.x) / 2;
                    ctx.bezierCurveTo(midX, n1.y, midX, n2.y, n2.x, n2.y);
                    ctx.stroke();
                });

                // Draw Packets
                for (let i = state.packets.length - 1; i >= 0; i--) {
                    const p = state.packets[i];
                    p.progress += p.speed;

                    const n1 = state.nodes.find((n: any) => n.id === p.fromId);
                    const n2 = state.nodes.find((n: any) => n.id === p.toId);

                    // Bezier calc matching link
                    const midX = (n1.x + n2.x) / 2;
                    const t = p.progress;
                    const invT = 1 - t;

                    // Cubic Bezier formula: (1-t)^3*P0 + 3*(1-t)^2*t*P1 + 3*(1-t)*t^2*P2 + t^3*P3
                    // Control points: P0=(n1.x, n1.y), P1=(midX, n1.y), P2=(midX, n2.y), P3=(n2.x, n2.y)

                    const x = invT*invT*invT*n1.x + 3*invT*invT*t*midX + 3*invT*t*t*midX + t*t*t*n2.x;
                    const y = invT*invT*invT*n1.y + 3*invT*invT*t*n1.y + 3*invT*t*t*n2.y + t*t*t*n2.y;

                    ctx.fillStyle = color;
                    ctx.shadowBlur = 10; ctx.shadowColor = color;
                    ctx.beginPath(); ctx.arc(x, y, 3, 0, Math.PI*2); ctx.fill();
                    ctx.shadowBlur = 0;

                    if (p.progress >= 1) {
                        // Trigger destination node
                        n2.active = 1.0;

                        // Propagate
                        const nextLinks = state.links.filter((l: any) => l.from === n2.id);
                        nextLinks.forEach((l: any) => {
                            state.packets.push({ fromId: l.from, toId: l.to, progress: 0, speed: 0.02 });
                        });

                        state.packets.splice(i, 1);
                    }
                }

                // Draw Nodes
                state.nodes.forEach((n: any) => {
                    const isActive = n.active > 0.01;
                    if (n.active > 0) n.active *= 0.95;

                    ctx.save();
                    ctx.translate(n.x, n.y);

                    // Node Shape
                    if (n.type === 'trigger') {
                        // Diamond
                        ctx.fillStyle = isActive ? color : '#1a1a1c';
                        ctx.strokeStyle = isActive ? '#fff' : 'rgba(255,255,255,0.2)';
                        ctx.beginPath(); ctx.moveTo(0, -20); ctx.lineTo(20, 0); ctx.lineTo(0, 20); ctx.lineTo(-20, 0); ctx.closePath();
                    } else if (n.type === 'process') {
                        // Rectangle
                        ctx.fillStyle = isActive ? color : '#1a1a1c';
                        ctx.strokeStyle = isActive ? '#fff' : 'rgba(255,255,255,0.2)';
                        ctx.beginPath(); ctx.roundRect(-40, -20, 80, 40, 4);
                    } else {
                        // Pill (Action)
                        ctx.fillStyle = isActive ? color : '#1a1a1c';
                        ctx.strokeStyle = isActive ? '#fff' : 'rgba(255,255,255,0.2)';
                        ctx.beginPath(); ctx.roundRect(-30, -15, 60, 30, 15);
                    }

                    ctx.globalAlpha = isActive ? 0.8 : 0.5;
                    ctx.fill();
                    ctx.globalAlpha = 1;
                    ctx.lineWidth = 1;
                    ctx.stroke();

                    // Label
                    ctx.fillStyle = '#fff';
                    ctx.font = '9px monospace';
                    ctx.textAlign = 'center';
                    ctx.textBaseline = 'middle';
                    // ctx.fillText(n.label, 0, 30); // Below node

                    // Draw Label Box
                    const textW = ctx.measureText(n.label).width;
                    ctx.fillStyle = 'rgba(0,0,0,0.6)';
                    ctx.fillRect(-textW/2 - 4, 22, textW + 8, 14);
                    ctx.fillStyle = isActive ? color : '#888';
                    ctx.fillText(n.label, 0, 29);

                    ctx.restore();
                });
            }
            else if (mode === 'core') {
                if (Math.random() > 0.96) {
                    state.nodes[0].active = 1; 
                    const startLink = state.links.filter((l: any) => l.from === 0)[Math.floor(Math.random() * 6)];
                    if (startLink) {
                        state.particles.push({
                            linkIdx: state.links.indexOf(startLink),
                            t: 0,
                            speed: 0.08
                        });
                    }
                }

                ctx.translate(cx, cy);
                ctx.rotate(time * 0.05);

                ctx.strokeStyle = 'rgba(255,255,255,0.08)';
                ctx.lineWidth = 1;
                ctx.beginPath();
                state.links.forEach((l: any) => {
                    const n1 = state.nodes[l.from];
                    const n2 = state.nodes[l.to];
                    ctx.moveTo(n1.x, n1.y);
                    ctx.lineTo(n2.x, n2.y);
                });
                ctx.stroke();

                state.nodes.forEach((n:any) => {
                    if (n.active > 0) {
                        ctx.fillStyle = color;
                        ctx.shadowBlur = 10 * n.active;
                        ctx.shadowColor = color;
                        n.active -= 0.05;
                    } else {
                        ctx.fillStyle = n.layer === 0 ? color : 'rgba(255,255,255,0.3)';
                        ctx.shadowBlur = 0;
                    }
                    const size = n.layer === 0 ? 4 : 2;
                    ctx.beginPath(); ctx.arc(n.x, n.y, size, 0, Math.PI*2); ctx.fill();
                    ctx.shadowBlur = 0;
                });

                for(let i=state.particles.length-1; i>=0; i--) {
                    const p = state.particles[i];
                    p.t += p.speed;
                    const link = state.links[p.linkIdx];
                    if (!link) { state.particles.splice(i,1); continue; }
                    const n1 = state.nodes[link.from];
                    const n2 = state.nodes[link.to];
                    const currX = n1.x + (n2.x - n1.x) * p.t;
                    const currY = n1.y + (n2.y - n1.y) * p.t;
                    ctx.fillStyle = '#fff';
                    ctx.shadowBlur = 5; ctx.shadowColor = '#fff';
                    ctx.fillRect(currX-1.5, currY-1.5, 3, 3);
                    ctx.shadowBlur = 0;
                    if (p.t >= 1) {
                        n2.active = 1;
                        if (n2.layer < 3 && Math.random() > 0.3) {
                            const nextLinks = state.links.map((l: any, idx: number) => ({...l, idx})).filter((l: any) => l.from === link.to);
                            if (nextLinks.length > 0) {
                                const nextL = nextLinks[Math.floor(Math.random() * nextLinks.length)];
                                state.particles.push({ linkIdx: nextL.idx, t: 0, speed: 0.08 });
                            }
                        }
                        state.particles.splice(i, 1);
                    }
                }
                ctx.rotate(-time * 0.05);
                ctx.translate(-cx, -cy);
            }
            else if (mode === 'swarm') {
                const beltY = h * 0.65; // Base input level (Centered Lower)
                const inputEnd = w * 0.45;
                const outputStart = w * 0.55;
                const agentX = w * 0.5;
                const agentBaseY = beltY + 40;

                const boxSize = 18;
                const speed = 1.0; // Slower conveyor
                const animSpeed = 0.03;

                const COLORS = ['#22d3ee', '#a78bfa', '#fbbf24']; // Cyan, Purple, Amber
                const TARGET_YS = [beltY - 80, beltY - 40, beltY];

                const lastBox = state.boxes.length > 0 ? state.boxes[state.boxes.length - 1] : null;
                const safeToSpawn = !lastBox || (lastBox.x > 80); 

                if (safeToSpawn && Math.random() > 0.99) {
                    const typeIdx = Math.floor(Math.random() * 3);
                    state.boxes.push({
                        x: -20,
                        y: beltY - boxSize,
                        w: boxSize,
                        h: boxSize,
                        color: COLORS[typeIdx],
                        targetLane: typeIdx,
                        state: 'conveyor_in' // conveyor_in, lifted, conveyor_out
                    });
                }

                ctx.fillStyle = 'rgba(255,255,255,0.1)';
                ctx.fillRect(0, beltY, inputEnd, 4);
                TARGET_YS.forEach(y => {
                    ctx.fillRect(outputStart, y + boxSize, w - outputStart, 4);
                });

                ctx.fillStyle = 'rgba(255,255,255,0.2)';
                const dashOffset = (time * 60) % 40; 
                for(let i=0; i<inputEnd; i+=40) {
                    const x = i + dashOffset;
                    if(x < inputEnd) ctx.fillRect(x, beltY, 4, 4);
                }
                TARGET_YS.forEach(y => {
                    for(let i=outputStart; i<w; i+=40) {
                        const x = i + dashOffset; 
                        if(x > outputStart) ctx.fillRect(x, y + boxSize, 4, 4);
                    }
                });

                const agent = state.agent;
                ctx.fillStyle = '#333';
                ctx.fillRect(agentX - 15, agentBaseY - 20, 30, 20); 

                const pivotX = agentX;
                const pivotY = agentBaseY - 20;

                let armX = pivotX;
                let armY = beltY - 60; // Idle height
                let grabberGap = 10;

                if (agent.state === 'idle') {
                    const target = state.boxes.find((b: any) => 
                        b.state === 'conveyor_in' && 
                        b.x > inputEnd - 60 && 
                        b.x < inputEnd
                    );
                    if (target) {
                        agent.state = 'reaching';
                        agent.targetBox = target;
                        agent.t = 0;
                    }
                }

                if (agent.state === 'reaching') {
                    agent.t += animSpeed;
                    const t = Math.min(1, agent.t);
                    const b = agent.targetBox;
                    if(b.x < inputEnd - 20) b.x += speed;
                    armX = pivotX + (b.x + b.w/2 - pivotX) * t;
                    armY = (pivotY - 80) + (b.y - (pivotY - 80)) * t;
                    if (t >= 1) { agent.state = 'grasping'; agent.t = 0; }
                } 
                else if (agent.state === 'grasping') {
                    agent.t += animSpeed * 2;
                    grabberGap = 10 * (1 - Math.min(1, agent.t));
                    armX = agent.targetBox.x + agent.targetBox.w/2;
                    armY = agent.targetBox.y;
                    if (agent.t >= 1) { agent.state = 'moving'; agent.targetBox.state = 'lifted'; agent.t = 0; }
                }
                else if (agent.state === 'moving') {
                    agent.t += animSpeed;
                    const t = Math.min(1, agent.t);
                    const b = agent.targetBox;
                    const targetY = TARGET_YS[b.targetLane];

                    const startX = inputEnd - 20;
                    const targetX = outputStart + 20;

                    armX = startX + (targetX - startX) * t;
                    const midY = Math.min(beltY, targetY) - 60;
                    armY = (1-t)*(1-t)*beltY + 2*(1-t)*t*midY + t*t*targetY;

                    grabberGap = 0;
                    b.x = armX - b.w/2;
                    b.y = armY;

                    if (t >= 1) { agent.state = 'releasing'; agent.t = 0; }
                }
                else if (agent.state === 'releasing') {
                    agent.t += animSpeed * 2;
                    const b = agent.targetBox;
                    armX = b.x + b.w/2;
                    armY = b.y;
                    grabberGap = 10 * Math.min(1, agent.t);

                    if (agent.t >= 1) {
                        b.state = 'conveyor_out';
                        b.y = TARGET_YS[b.targetLane];
                        agent.state = 'returning';
                        agent.targetBox = null;
                        agent.t = 0;
                    }
                }
                else if (agent.state === 'returning') {
                    agent.t += animSpeed;
                    const t = Math.min(1, agent.t);
                    const startX = outputStart + 20;
                    const startY = armY;
                    const targetX = pivotX;
                    const targetY = beltY - 60;
                    armX = startX + (targetX - startX) * t;
                    armY = startY + (targetY - startY) * t;
                    if (t >= 1) agent.state = 'idle';
                }
                else {
                    armX = pivotX + Math.sin(time * 2) * 5;
                    armY = beltY - 60 + Math.cos(time * 3) * 5;
                }

                ctx.strokeStyle = color;
                ctx.lineWidth = 2;
                ctx.beginPath();
                ctx.moveTo(pivotX, pivotY);
                const elbowX = (pivotX + armX) / 2 - 20; 
                const elbowY = Math.min(pivotY, armY) - 30;
                ctx.quadraticCurveTo(elbowX, elbowY, armX, armY);
                ctx.stroke();

                ctx.fillStyle = '#fff';
                ctx.beginPath(); ctx.arc(pivotX, pivotY, 3, 0, Math.PI*2); ctx.fill();
                ctx.beginPath(); ctx.arc(armX, armY, 3, 0, Math.PI*2); ctx.fill();

                ctx.save();
                ctx.translate(armX, armY);
                ctx.fillStyle = color;
                ctx.fillRect(-8 - grabberGap/2, -5, 4, 15);
                ctx.fillRect(4 + grabberGap/2, -5, 4, 15);
                ctx.restore();

                for (let i = state.boxes.length - 1; i >= 0; i--) {
                    const b = state.boxes[i];
                    if (b.state === 'conveyor_in') {
                        if (agent.targetBox !== b || agent.state === 'reaching') {
                             if (b.x < inputEnd - 20) b.x += speed; 
                        }
                    } else if (b.state === 'conveyor_out') {
                        b.x += speed;
                    }
                    if (b.x > w + 20) { state.boxes.splice(i, 1); continue; }

                    ctx.fillStyle = b.color;
                    ctx.strokeStyle = '#fff';
                    ctx.lineWidth = 1;
                    ctx.fillRect(b.x, b.y, b.w, b.h);
                    ctx.strokeRect(b.x, b.y, b.w, b.h);
                    ctx.fillStyle = 'rgba(0,0,0,0.3)';
                    ctx.fillRect(b.x + 2, b.y + 2, 4, 4);
                }
            }
            else if (mode === 'translation') {
                const colWidth = 140; 
                const numCols = 2; 
                const SNIPPETS = ["POST /api/v1/ingest", "{ id: '8f3a' }", "WARN: Latency", "Converting...", "0x4F3E21", "SELECT * FROM logs", "Processing...", "struct Node", "ERROR: Timeout", "> System.init()"];

                if (state.columns.length === 0) {
                    state.columns = Array.from({ length: numCols }, (_, i) => ({
                        x: 20 + i * (colWidth + 10),
                        y: Math.random() * h,
                        speed: 0.5 + Math.random() * 0.5,
                        items: Array.from({ length: 15 }, () => ({
                            text: SNIPPETS[Math.floor(Math.random() * SNIPPETS.length)],
                            y: 0 
                        }))
                    }));
                }

                const gridStartX = w * 0.55;
                const gridCols = 6; const gridRows = 8;
                const cellW = (w * 0.4) / gridCols; const cellH = h / gridRows;
                if (state.grid.length === 0) {
                    for(let i=0; i<gridCols*gridRows; i++) {
                        state.grid.push({
                            x: gridStartX + (i % gridCols) * cellW + cellW/2,
                            y: Math.floor(i / gridCols) * cellH + cellH/2,
                            filled: false, alpha: 0.2
                        });
                    }
                }

                ctx.font = '10px monospace';
                ctx.textAlign = 'left';

                state.columns.forEach((col: any) => {
                    col.y -= col.speed;
                    if (col.y < -300) col.y = h; 

                    col.items.forEach((item: any, i: number) => {
                        const yPos = col.y + i * 20;
                        const drawnY = yPos % (h + 300) - 50;

                        if (drawnY > -20 && drawnY < h + 20) {
                            const isScanned = Math.abs(drawnY - h/2) < 20;
                            ctx.fillStyle = isScanned ? '#fff' : 'rgba(255,255,255,0.3)';
                            if (isScanned) {
                                if (Math.random() > 0.98) {
                                    const empty = state.grid.filter((g: any) => !g.filled);
                                    if (empty.length > 0) {
                                        const t = empty[Math.floor(Math.random() * empty.length)];
                                        t.filled = true;
                                        state.particles.push({
                                            x: col.x + 80, y: drawnY,
                                            tx: t.x, ty: t.y,
                                            progress: 0, speed: 0.05,
                                            target: t
                                        });
                                    }
                                }
                            }
                            ctx.fillText(item.text, col.x, drawnY);
                        }
                    });
                });

                ctx.fillStyle = color;
                ctx.globalAlpha = 0.1;
                ctx.fillRect(0, h/2 - 20, w * 0.45, 40);
                ctx.globalAlpha = 0.8;
                ctx.fillRect(0, h/2, w * 0.45, 1);

                ctx.globalAlpha = 1;
                for (let i = state.particles.length - 1; i >= 0; i--) {
                    const p = state.particles[i];
                    p.progress += p.speed;
                    const t = p.progress;
                    const lx = p.x + (p.tx - p.x) * t;
                    const ly = p.y + (p.ty - p.y) * t;

                    ctx.fillStyle = color;
                    ctx.fillRect(lx - 2, ly - 2, 4, 4);

                    if (p.progress >= 1) {
                        p.target.alpha = 1.0;
                        state.particles.splice(i, 1);
                    }
                }

                state.grid.forEach((cell: any) => {
                    if (cell.filled) cell.alpha = Math.max(0.4, cell.alpha - 0.02);
                    else cell.alpha = 0.1;
                    const s = Math.min(cellW, cellH) * 0.6;
                    ctx.strokeStyle = color; ctx.globalAlpha = cell.alpha; ctx.lineWidth = 1;
                    ctx.strokeRect(cell.x - s/2, cell.y - s/2, s, s);
                    if (cell.filled) {
                        ctx.fillStyle = color; ctx.globalAlpha = cell.alpha * 0.6;
                        ctx.fillRect(cell.x - s/2 + 2, cell.y - s/2 + 2, s - 4, s - 4);
                        if (Math.random() > 0.995) cell.filled = false;
                    }
                });
            }
            else if (mode === 'identity') {
                // --- "SkillStream": TikTok-style Corporate Learning Feed ---

                // --- DRAW LOOP ---

                // 1. UPDATE STATE
                state.feedTimer++;
                const card = state.feedCards[state.currentCardIndex];

                // Simulated Cursor Movement
                if (state.feedState === 'reading') {
                    // Wait for 1.5s then move to answer
                    if (state.feedTimer > 100) {
                        state.feedState = 'selecting';
                        // Target the correct answer button
                        // Assuming 2 options, button Y approx 70% down
                        const targetBtnX = w/2;
                        const targetBtnY = h * 0.7 + (card.correct === 0 ? 0 : 50); // Offset based on index
                        state.cursor.targetX = targetBtnX;
                        state.cursor.targetY = targetBtnY;
                    }
                } else if (state.feedState === 'selecting') {
                    // Move cursor
                    state.cursor.x += (state.cursor.targetX - state.cursor.x) * 0.1;
                    state.cursor.y += (state.cursor.targetY - state.cursor.y) * 0.1;

                    if (Math.abs(state.cursor.x - state.cursor.targetX) < 2 && Math.abs(state.cursor.y - state.cursor.targetY) < 2) {
                        // "Click"
                        state.feedState = 'feedback';
                        state.feedTimer = 0;
                        state.xp += 50;
                        state.streak += 1;

                        // Spawn confetti
                        for(let i=0; i<30; i++) {
                            state.particles.push({
                                x: state.cursor.x, y: state.cursor.y,
                                vx: (Math.random()-0.5)*10, vy: (Math.random()-0.5)*10 - 5,
                                life: 1.0, color: card.color
                            });
                        }
                    }
                } else if (state.feedState === 'feedback') {
                    if (state.feedTimer > 60) {
                        state.feedState = 'swiping';
                        state.feedTimer = 0;
                    }
                } else if (state.feedState === 'swiping') {
                    state.swipeOffset += ( -h - state.swipeOffset ) * 0.1;
                    if (Math.abs(state.swipeOffset - (-h)) < 5) {
                        // Reset for next card
                        state.currentCardIndex = (state.currentCardIndex + 1) % state.feedCards.length;
                        state.swipeOffset = 0;
                        state.feedState = 'reading';
                        state.feedTimer = 0;
                        // Reset cursor
                        state.cursor.x = w/2; state.cursor.y = h * 0.9;
                    }
                }

                // 2. RENDER UI
                ctx.save();

                // Main Container (Phone-ish)
                ctx.translate(0, state.swipeOffset);

                // Draw Current Card
                ctx.fillStyle = '#121214';
                ctx.fillRect(20, 20, w-40, h-40);

                // Progress Bar Top
                ctx.fillStyle = 'rgba(255,255,255,0.1)';
                ctx.fillRect(20, 20, w-40, 4);
                ctx.fillStyle = card.color;
                ctx.fillRect(20, 20, (w-40) * (state.feedTimer % 300 / 300), 4); // Dummy progress

                // Header
                ctx.font = 'bold 12px sans-serif';
                ctx.fillStyle = '#fff';
                ctx.textAlign = 'left';
                ctx.fillText(`🔥 ${state.streak}`, 35, 50);
                ctx.textAlign = 'right';
                ctx.fillText(`${state.xp} XP`, w-35, 50);

                // Question Content
                ctx.textAlign = 'center';
                ctx.font = 'bold 18px sans-serif';
                ctx.fillStyle = '#fff';
                ctx.fillText(card.q, w/2, h * 0.3);

                // Subtext / Context
                ctx.font = '12px monospace';
                ctx.fillStyle = 'rgba(255,255,255,0.6)';
                ctx.fillText(card.sub, w/2, h * 0.3 + 25);

                // Type Badge
                ctx.fillStyle = 'rgba(255,255,255,0.1)';
                const badgeW = 80;
                ctx.fillRect(w/2 - badgeW/2, h * 0.2 - 15, badgeW, 20);
                ctx.strokeStyle = card.color; ctx.strokeRect(w/2 - badgeW/2, h * 0.2 - 15, badgeW, 20);
                ctx.fillStyle = card.color; ctx.font = 'bold 9px sans-serif';
                ctx.fillText(card.type, w/2, h * 0.2 - 2);

                // Options Buttons
                card.opts.forEach((opt: string, i: number) => {
                    const btnY = h * 0.7 + i * 50;
                    const isCorrect = i === card.correct;
                    const isSelected = state.feedState === 'feedback' && isCorrect;

                    // Button Box
                    ctx.fillStyle = isSelected ? card.color : 'rgba(255,255,255,0.05)';
                    if (isSelected) ctx.shadowColor = card.color; ctx.shadowBlur = 20;
                    ctx.fillRect(40, btnY - 20, w-80, 40);
                    ctx.shadowBlur = 0;

                    // Border
                    ctx.strokeStyle = 'rgba(255,255,255,0.1)';
                    ctx.lineWidth = 1;
                    ctx.strokeRect(40, btnY - 20, w-80, 40);

                    // Text
                    ctx.fillStyle = isSelected ? '#000' : '#fff';
                    ctx.font = 'bold 12px sans-serif';
                    ctx.fillText(opt, w/2, btnY + 5);
                });

                // Particles (Confetti)
                state.particles.forEach((p: any, i: number) => {
                    p.x += p.vx; p.y += p.vy; p.vy += 0.5; // Gravity
                    p.life -= 0.02;
                    if (p.life <= 0) state.particles.splice(i, 1);

                    ctx.fillStyle = p.color;
                    ctx.globalAlpha = p.life;
                    ctx.fillRect(p.x, p.y, 4, 4);
                });
                ctx.globalAlpha = 1;

                ctx.restore(); // End Translate

                // 3. DRAW CURSOR (Simulation Overlay)
                // Draw cursor only if not swiping
                if (state.feedState !== 'swiping') {
                    ctx.fillStyle = 'rgba(255, 255, 255, 0.8)';
                    ctx.beginPath(); ctx.arc(state.cursor.x, state.cursor.y, 8, 0, Math.PI*2); ctx.fill();
                    // Ripple on click
                    if (state.feedState === 'feedback' && state.feedTimer < 10) {
                        ctx.strokeStyle = 'rgba(255, 255, 255, 0.5)';
                        ctx.beginPath(); ctx.arc(state.cursor.x, state.cursor.y, 20 + state.feedTimer*2, 0, Math.PI*2); ctx.stroke();
                    }
                }
            }

            ctx.globalAlpha = 1;
            frameId = requestAnimationFrame(render);
        };

        const observer = new ResizeObserver(() => { resize(); });
        observer.observe(container);
        resize();
        render();

        return () => {
            observer.disconnect();
            cancelAnimationFrame(frameId);
        };
    }, [mode, color]);

    return (
        <div ref={containerRef} className="w-full h-full relative overflow-hidden bg-[#0c0c0e]">
            <canvas ref={canvasRef} className="block absolute top-0 left-0" />
            <div className="absolute inset-0 pointer-events-none opacity-20" style={{ backgroundImage: 'linear-gradient(rgba(18, 16, 16, 0) 50%, rgba(0, 0, 0, 0.25) 50%), linear-gradient(90deg, rgba(255, 0, 0, 0.06), rgba(0, 255, 0, 0.02), rgba(0, 0, 255, 0.06))', backgroundSize: '100% 2px, 3px 100%' }} />
        </div>
    );
};

import React, { useEffect, useRef } from 'react';

interface SectionVisualizerProps {
    mode: 'search' | 'redaction' | 'logic' | 'core' | 'shield' | 'swarm' | 'predictive' | 'translation' | 'identity';
    color: string;
}

export const SectionVisualizer: React.FC<SectionVisualizerProps> = ({ mode, color }) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const containerRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const canvas = canvasRef.current;
        const container = containerRef.current;
        if (!canvas || !container) return;

        const ctx = canvas.getContext('2d', { alpha: true });
        if (!ctx) return;

        let frameId: number;
        let time = 0;

        // --- STATE MANAGEMENT ---
        const state: any = {
            width: 0,
            height: 0,
            particles: [],
            nodes: [],
            links: [], 
            grid: [],
            columns: [], 
            task: null, 
            agent: { state: 'idle', t: 0, heldBox: null, armHeight: 0, armExt: 0 },
            boxes: [], 
            stack: [],
            // Identity Mode (Learning Feed) State
            feedState: 'reading', // reading -> selecting -> feedback -> swiping
            feedTimer: 0,
            currentCardIndex: 0,
            swipeOffset: 0,
            streak: 12,
            xp: 850,
            cursor: { x: 0, y: 0, targetX: 0, targetY: 0, clicking: false },
            feedCards: [
                { 
                    type: 'CYBER_SECURITY', 
                    bg: ['#1e1b4b', '#312e81'], // Indigo
                    author: "@SecurOps",
                    q: "Suspicious Email Detected", 
                    sub: "Sender domain is 'goggle.com'. What's the protocol?", 
                    opts: ["Report & Delete", "Reply to Verify"], 
                    correct: 0, 
                    likes: "12.4k" 
                },
                { 
                    type: 'SAFETY_PROTO', 
                    bg: ['#451a03', '#78350f'], // Amber
                    author: "@PlantManager",
                    q: "Forklift in Zone B", 
                    sub: "Pedestrian light is flashing red.", 
                    opts: ["Right of Way", "Stop & Wait"], 
                    correct: 1, 
                    likes: "8.2k" 
                },
                { 
                    type: 'DATA_PRIVACY', 
                    bg: ['#022c22', '#115e59'], // Emerald
                    author: "@ComplianceBot",
                    q: "PII in Comments?", 
                    sub: "Customer put SSN in 'Notes' field.", 
                    opts: ["Ignore", "Redact Immediately"], 
                    correct: 1, 
                    likes: "45k" 
                },
                { 
                    type: 'HR_POLICY', 
                    bg: ['#4c0519', '#9f1239'], // Rose
                    author: "@PeopleTeam",
                    q: "Gift Policy", 
                    sub: "Vendor offers $200 tickets.", 
                    opts: ["Decline", "Accept"], 
                    correct: 0, 
                    likes: "2.1k" 
                }
            ],
            // Logic/Strategy Mode State
            packets: [],
            initializedMode: null
        };

        const resize = () => {
            const rect = container.getBoundingClientRect();
            const dpr = window.devicePixelRatio || 1;

            canvas.width = rect.width * dpr;
            canvas.height = rect.height * dpr;

            canvas.style.width = `${rect.width}px`;
            canvas.style.height = `${rect.height}px`;

            ctx.scale(dpr, dpr);

            state.width = rect.width;
            state.height = rect.height;

            if (mode !== state.initializedMode) {
                init(rect.width, rect.height);
            }
        };

        const init = (w: number, h: number) => {
            state.particles = [];
            state.nodes = [];
            state.links = [];
            state.grid = [];
            state.columns = [];
            state.task = null;
            state.boxes = [];
            state.stack = [];
            state.packets = [];
            state.agent = { state: 'idle', t: 0, heldBox: null, armHeight: 0, armExt: 0 };

            // Identity specific
            state.feedState = 'reading';
            state.feedTimer = 0;
            state.currentCardIndex = 0;
            state.swipeOffset = 0;
            state.streak = 12;
            state.cursor = { x: w/2, y: h*0.8, targetX: w/2, targetY: h*0.8, clicking: false };

            state.initializedMode = mode;

            if (mode === 'search') {
                const particleCount = 80;
                for(let i=0; i<particleCount; i++) {
                    state.particles.push({
                        x: Math.random() * w,
                        y: Math.random() * h,
                        vx: 2 + Math.random() * 1.5,
                        vy: (Math.random() - 0.5) * 0.5,
                        targetLane: Math.floor(Math.random() * 5),
                        size: 0.5 + Math.random() * 0.5
                    });
                }
            }
            else if (mode === 'logic') {
                // STRATEGY BUILDER
                state.nodes.push({ id: 0, x: w * 0.15, y: h * 0.3, label: "DEMAND SPIKE", type: 'trigger', active: 0 });
                state.nodes.push({ id: 1, x: w * 0.15, y: h * 0.7, label: "INVENTORY LOW", type: 'trigger', active: 0 });
                state.nodes.push({ id: 2, x: w * 0.45, y: h * 0.5, label: "ALLOCATION LOGIC", type: 'process', active: 0 });
                state.nodes.push({ id: 3, x: w * 0.75, y: h * 0.25, label: "PRIORITY: RETAIL", type: 'action', active: 0 });
                state.nodes.push({ id: 4, x: w * 0.75, y: h * 0.75, label: "LIMIT WHOLESALE", type: 'action', active: 0 });
                state.links.push({ from: 0, to: 2 });
                state.links.push({ from: 1, to: 2 });
                state.links.push({ from: 2, to: 3 });
                state.links.push({ from: 2, to: 4 });
            }
            // ... (Other modes omitted for brevity, logic remains in 'render')
        };

        const render = () => {
            time += 0.01;
            const w = state.width;
            const h = state.height;
            const cx = w/2;
            const cy = h/2;

            ctx.clearRect(0, 0, w, h);

            if (mode === 'identity') {
                // --- "SkillStream": TikTok-style Corporate Learning Feed ---

                // 1. UPDATE STATE & PHYSICS
                state.feedTimer++;
                const card = state.feedCards[state.currentCardIndex];

                // -- Cursor Simulation Logic --
                if (state.feedState === 'reading') {
                    // Hover around a bit
                    state.cursor.targetX = w/2 + Math.sin(time) * 20;
                    state.cursor.targetY = h * 0.75 + Math.cos(time * 1.5) * 20;

                    if (state.feedTimer > 120) { // Wait 2s before acting
                        state.feedState = 'selecting';
                    }
                } 
                else if (state.feedState === 'selecting') {
                    // Move to correct button
                    const btnH = 50;
                    const spacing = 15;
                    const btnY = h * 0.65 + card.correct * (btnH + spacing) + btnH/2;

                    state.cursor.targetX = w/2;
                    state.cursor.targetY = btnY;

                    // Snap click when close
                    const dx = state.cursor.targetX - state.cursor.x;
                    const dy = state.cursor.targetY - state.cursor.y;
                    if (Math.sqrt(dx*dx + dy*dy) < 5) {
                        state.cursor.clicking = true;
                        state.feedState = 'feedback';
                        state.feedTimer = 0;
                        state.streak++;
                        state.xp += 150;

                        // Explosion
                        for(let i=0; i<40; i++) {
                            state.particles.push({
                                x: state.cursor.x,
                                y: state.cursor.y,
                                vx: (Math.random()-0.5) * 15,
                                vy: (Math.random()-0.5) * 15 - 5,
                                life: 1.0,
                                color: ['#4ade80', '#fbbf24', '#ffffff'][Math.floor(Math.random()*3)]
                            });
                        }
                    }
                }
                else if (state.feedState === 'feedback') {
                    state.cursor.clicking = false;
                    if (state.feedTimer > 80) { // Wait 1.5s viewing success
                        state.feedState = 'swiping';
                        state.cursor.targetY = h * 0.2; // Move up to swipe
                        state.feedTimer = 0;
                    }
                }
                else if (state.feedState === 'swiping') {
                    // Lerp Offset
                    state.swipeOffset += (-h - state.swipeOffset) * 0.15;

                    // Reset
                    if (Math.abs(state.swipeOffset + h) < 5) {
                        state.currentCardIndex = (state.currentCardIndex + 1) % state.feedCards.length;
                        state.swipeOffset = 0;
                        state.feedState = 'reading';
                        state.feedTimer = 0;
                        state.cursor.y = h + 100; // Reset cursor pos
                    }
                }

                // Cursor Physics
                state.cursor.x += (state.cursor.targetX - state.cursor.x) * 0.15;
                state.cursor.y += (state.cursor.targetY - state.cursor.y) * 0.15;

                // -- RENDER --

                ctx.save();
                ctx.translate(0, state.swipeOffset);

                // 1. Dynamic Video Background
                const grad = ctx.createLinearGradient(0, 0, 0, h);
                grad.addColorStop(0, card.bg[0]);
                grad.addColorStop(1, card.bg[1]);
                ctx.fillStyle = grad;
                ctx.fillRect(0, 0, w, h);

                // Animated BG Elements (Subtle movement)
                ctx.save();
                ctx.globalAlpha = 0.1;
                ctx.fillStyle = '#fff';
                for(let i=0; i<5; i++) {
                    const bx = (time * 20 + i * 50) % w;
                    const by = (Math.sin(time + i) * 100 + h/2);
                    ctx.beginPath(); ctx.arc(bx, by, 50 + i*20, 0, Math.PI*2); ctx.fill();
                }
                ctx.restore();

                // 2. Right Sidebar (TikTok style actions)
                const rightMargin = w - 40;
                const bottomMargin = h - 100;

                // Avatar
                ctx.beginPath(); ctx.arc(rightMargin, bottomMargin - 150, 20, 0, Math.PI*2); 
                ctx.fillStyle = '#fff'; ctx.fill();
                ctx.lineWidth = 2; ctx.strokeStyle = '#ef4444'; ctx.stroke();
                // Plus icon
                ctx.fillStyle = '#ef4444'; ctx.beginPath(); ctx.arc(rightMargin, bottomMargin - 135, 8, 0, Math.PI*2); ctx.fill();

                // Heart
                ctx.fillStyle = state.feedState === 'feedback' || state.feedState === 'swiping' ? '#ef4444' : 'rgba(255,255,255,0.8)';
                ctx.font = '24px serif'; ctx.textAlign='center'; ctx.fillText('♥', rightMargin, bottomMargin - 90);
                ctx.font = '10px sans-serif'; ctx.fillStyle='#fff'; ctx.fillText(card.likes, rightMargin, bottomMargin - 75);

                // Share
                ctx.fillStyle = 'rgba(255,255,255,0.8)';
                ctx.font = '24px serif'; ctx.fillText('➤', rightMargin, bottomMargin - 30);
                ctx.font = '10px sans-serif'; ctx.fillStyle='#fff'; ctx.fillText("Share", rightMargin, bottomMargin - 15);

                // 3. Bottom Content Overlay
                ctx.textAlign = 'left';

                // Author
                ctx.font = 'bold 12px sans-serif'; ctx.fillStyle = '#fff';
                ctx.fillText(card.author, 20, h * 0.45);

                // Question (The Caption)
                ctx.font = 'bold 18px sans-serif'; 
                const lines = card.q.split(' '); // Simple wrap logic could go here
                ctx.fillText(card.q, 20, h * 0.45 + 25);

                // Subtext
                ctx.font = '12px sans-serif'; ctx.fillStyle = 'rgba(255,255,255,0.8)';
                ctx.fillText(card.sub, 20, h * 0.45 + 45);

                // 4. Interactive Quiz Buttons
                card.opts.forEach((opt: string, i: number) => {
                    const btnH = 50;
                    const spacing = 15;
                    const btnW = w * 0.75;
                    const btnX = (w - btnW) / 2;
                    const btnY = h * 0.65 + i * (btnH + spacing);

                    const isCorrect = i === card.correct;
                    const isSelected = (state.feedState === 'feedback' || state.feedState === 'swiping') && isCorrect;

                    // Glassmorphism Button
                    ctx.fillStyle = isSelected ? '#22c55e' : 'rgba(255,255,255,0.15)';
                    if (isSelected) {
                        ctx.shadowColor = '#22c55e'; ctx.shadowBlur = 20;
                    } else {
                        ctx.shadowColor = 'transparent'; ctx.shadowBlur = 0;
                    }

                    ctx.beginPath(); ctx.roundRect(btnX, btnY, btnW, btnH, 12); ctx.fill();

                    // Text
                    ctx.fillStyle = '#fff'; ctx.font = 'bold 13px sans-serif'; ctx.textAlign = 'center';
                    ctx.fillText(opt, w/2, btnY + 30);

                    // Reset Shadow
                    ctx.shadowBlur = 0;
                });

                // 5. Feedback Banner (Duolingo Style)
                if (state.feedState === 'feedback' || state.feedState === 'swiping') {
                    const bannerY = state.feedState === 'feedback' ? 
                        h - 80 - Math.min(1, state.feedTimer/10) * 20 : // Pop up
                        h - 100 + state.feedTimer; // Slide down

                    ctx.fillStyle = '#22c55e';
                    ctx.fillRect(0, bannerY, w, 150);

                    ctx.fillStyle = '#fff';
                    ctx.font = 'bold 20px sans-serif'; ctx.textAlign = 'left';
                    ctx.fillText("Nice job!", 20, bannerY + 40);
                    ctx.font = '12px sans-serif';
                    ctx.fillText(`Streak: ${state.streak} days 🔥`, 20, bannerY + 60);
                }

                // 6. Particles
                for (let i = state.particles.length - 1; i >= 0; i--) {
                    const p = state.particles[i];
                    p.x += p.vx;
                    p.y += p.vy;
                    p.vy += 0.8; // Gravity
                    p.life -= 0.02;

                    if (p.life <= 0) {
                        state.particles.splice(i, 1);
                        continue;
                    }

                    ctx.fillStyle = p.color;
                    ctx.globalAlpha = p.life;
                    ctx.fillRect(p.x, p.y, 6, 6); // Confetti squares
                }
                ctx.globalAlpha = 1;

                // 7. Top Header (Progress)
                ctx.fillStyle = 'rgba(0,0,0,0.2)';
                ctx.fillRect(0, 0, w, 60);

                // Progress bar
                ctx.fillStyle = 'rgba(255,255,255,0.2)';
                ctx.fillRect(20, 20, w-40, 4);
                ctx.fillStyle = '#fff';
                // Simulated progress
                const prog = ((state.currentCardIndex + 1) / state.feedCards.length) * (w-40);
                ctx.fillRect(20, 20, prog, 4);

                ctx.restore(); // End Swipe Transform

                // 8. Simulated Cursor
                if (state.feedState !== 'swiping') {
                    ctx.shadowBlur = 10; ctx.shadowColor = 'rgba(0,0,0,0.5)';
                    ctx.fillStyle = '#fff';
                    // Pointer shape
                    ctx.beginPath();
                    ctx.moveTo(state.cursor.x, state.cursor.y);
                    ctx.lineTo(state.cursor.x + 12, state.cursor.y + 12);
                    ctx.lineTo(state.cursor.x + 5, state.cursor.y + 12);
                    ctx.lineTo(state.cursor.x, state.cursor.y + 18);
                    ctx.closePath();
                    ctx.fill();

                    // Click Ripple
                    if (state.cursor.clicking) {
                        ctx.strokeStyle = 'rgba(255,255,255,0.8)';
                        ctx.lineWidth = 2;
                        ctx.beginPath(); ctx.arc(state.cursor.x, state.cursor.y, 20, 0, Math.PI*2); ctx.stroke();
                    }
                    ctx.shadowBlur = 0;
                }
            }
            // ... (Existing render logic for other modes)
            else if (mode === 'search') {
                const processLine = w * 0.4;
                const laneCount = 5;
                const laneHeight = h / laneCount;

                ctx.lineWidth = 1;
                ctx.strokeStyle = 'rgba(255, 255, 255, 0.08)';
                for(let i=0; i<laneCount; i++) {
                    const ly = i * laneHeight + laneHeight/2;
                    ctx.beginPath(); ctx.moveTo(processLine, ly); ctx.lineTo(w, ly); ctx.stroke();
                }

                const scannerGlow = ctx.createLinearGradient(processLine, 0, processLine + 60, 0);
                scannerGlow.addColorStop(0, color);
                scannerGlow.addColorStop(1, 'transparent');
                ctx.fillStyle = scannerGlow;
                ctx.globalAlpha = 0.15;
                ctx.fillRect(processLine, 0, 60, h);

                ctx.fillStyle = color;
                ctx.globalAlpha = 0.8;
                ctx.fillRect(processLine, 0, 2, h);

                state.particles.forEach((p: any) => {
                    p.x += p.vx;
                    if (p.x < processLine) {
                        p.y += p.vy;
                        if (p.y < 0) p.y += h;
                        if (p.y > h) p.y -= h;
                        ctx.fillStyle = 'rgba(255, 255, 255, 0.4)';
                        ctx.globalAlpha = 0.6;
                        ctx.beginPath(); ctx.arc(p.x, p.y, p.size * 2, 0, Math.PI*2); ctx.fill();
                    } else {
                        const targetY = p.targetLane * laneHeight + laneHeight/2;
                        p.y += (targetY - p.y) * 0.15; 
                        p.x += 1.5; 
                        ctx.fillStyle = color;
                        ctx.globalAlpha = 1;
                        const packetWidth = 20 * p.size;
                        const packetHeight = 4;
                        ctx.shadowColor = color; ctx.shadowBlur = 10;
                        ctx.fillRect(p.x, p.y - packetHeight/2, packetWidth, packetHeight);
                        ctx.shadowBlur = 0;
                    }
                    if (p.x > w + 50) {
                        p.x = -20;
                        p.y = Math.random() * h;
                        p.vx = 2 + Math.random() * 1.5;
                        p.targetLane = Math.floor(Math.random() * laneCount);
                    }
                });
            }
            else if (mode === 'redaction') {
                const scanY = (time * 100) % (h + 100) - 50;
                state.particles.forEach((p: any) => {
                    const dist = Math.abs(p.y - scanY);
                    if (dist < 50) {
                        ctx.fillStyle = color;
                        ctx.globalAlpha = 1 - (dist/50);
                        ctx.fillRect(p.x, p.y, p.w, p.h);
                    } else {
                        ctx.fillStyle = 'rgba(255,255,255,0.05)';
                        ctx.globalAlpha = 1;
                        ctx.fillRect(p.x, p.y, p.w, p.h);
                    }
                });
                ctx.fillStyle = '#fff';
                ctx.fillRect(0, scanY, w, 2);
            }
            else if (mode === 'logic') {
                // Spawn Packets
                if (Math.random() > 0.98) {
                    const startNodes = state.nodes.filter((n: any) => n.type === 'trigger');
                    const start = startNodes[Math.floor(Math.random() * startNodes.length)];
                    state.nodes.forEach((n: any) => { if(n.id === start.id) n.active = 1.0; });

                    // Find links from this start
                    const links = state.links.filter((l: any) => l.from === start.id);
                    links.forEach((l: any) => {
                        state.packets.push({
                            fromId: l.from, toId: l.to, progress: 0, speed: 0.02 + Math.random() * 0.01
                        });
                    });
                }

                // Draw Links
                ctx.lineWidth = 2;
                state.links.forEach((l: any) => {
                    const n1 = state.nodes.find((n: any) => n.id === l.from);
                    const n2 = state.nodes.find((n: any) => n.id === l.to);

                    const grad = ctx.createLinearGradient(n1.x, n1.y, n2.x, n2.y);
                    grad.addColorStop(0, 'rgba(255,255,255,0.1)');
                    grad.addColorStop(1, 'rgba(255,255,255,0.05)');
                    ctx.strokeStyle = grad;

                    ctx.beginPath();
                    ctx.moveTo(n1.x, n1.y);
                    const midX = (n1.x + n2.x) / 2;
                    ctx.bezierCurveTo(midX, n1.y, midX, n2.y, n2.x, n2.y);
                    ctx.stroke();
                });

                // Draw Packets
                for (let i = state.packets.length - 1; i >= 0; i--) {
                    const p = state.packets[i];
                    p.progress += p.speed;

                    const n1 = state.nodes.find((n: any) => n.id === p.fromId);
                    const n2 = state.nodes.find((n: any) => n.id === p.toId);

                    const midX = (n1.x + n2.x) / 2;
                    const t = p.progress;
                    const invT = 1 - t;

                    const x = invT*invT*invT*n1.x + 3*invT*invT*t*midX + 3*invT*t*t*midX + t*t*t*n2.x;
                    const y = invT*invT*invT*n1.y + 3*invT*invT*t*n1.y + 3*invT*t*t*n2.y + t*t*t*n2.y;

                    ctx.fillStyle = color;
                    ctx.shadowBlur = 10; ctx.shadowColor = color;
                    ctx.beginPath(); ctx.arc(x, y, 3, 0, Math.PI*2); ctx.fill();
                    ctx.shadowBlur = 0;

                    if (p.progress >= 1) {
                        n2.active = 1.0;
                        const nextLinks = state.links.filter((l: any) => l.from === n2.id);
                        nextLinks.forEach((l: any) => {
                            state.packets.push({ fromId: l.from, toId: l.to, progress: 0, speed: 0.02 });
                        });
                        state.packets.splice(i, 1);
                    }
                }

                // Draw Nodes
                state.nodes.forEach((n: any) => {
                    const isActive = n.active > 0.01;
                    if (n.active > 0) n.active *= 0.95;

                    ctx.save();
                    ctx.translate(n.x, n.y);

                    if (n.type === 'trigger') {
                        ctx.fillStyle = isActive ? color : '#1a1a1c';
                        ctx.strokeStyle = isActive ? '#fff' : 'rgba(255,255,255,0.2)';
                        ctx.beginPath(); ctx.moveTo(0, -20); ctx.lineTo(20, 0); ctx.lineTo(0, 20); ctx.lineTo(-20, 0); ctx.closePath();
                    } else if (n.type === 'process') {
                        ctx.fillStyle = isActive ? color : '#1a1a1c';
                        ctx.strokeStyle = isActive ? '#fff' : 'rgba(255,255,255,0.2)';
                        ctx.beginPath(); ctx.roundRect(-40, -20, 80, 40, 4);
                    } else {
                        ctx.fillStyle = isActive ? color : '#1a1a1c';
                        ctx.strokeStyle = isActive ? '#fff' : 'rgba(255,255,255,0.2)';
                        ctx.beginPath(); ctx.roundRect(-30, -15, 60, 30, 15);
                    }

                    ctx.globalAlpha = isActive ? 0.8 : 0.5;
                    ctx.fill();
                    ctx.globalAlpha = 1;
                    ctx.lineWidth = 1;
                    ctx.stroke();

                    ctx.fillStyle = '#fff';
                    ctx.font = '9px monospace';
                    ctx.textAlign = 'center';
                    ctx.textBaseline = 'middle';

                    const textW = ctx.measureText(n.label).width;
                    ctx.fillStyle = 'rgba(0,0,0,0.6)';
                    ctx.fillRect(-textW/2 - 4, 22, textW + 8, 14);
                    ctx.fillStyle = isActive ? color : '#888';
                    ctx.fillText(n.label, 0, 29);

                    ctx.restore();
                });
            }
            else if (mode === 'core') {
                if (Math.random() > 0.96) {
                    state.nodes[0].active = 1; 
                    const startLink = state.links.filter((l: any) => l.from === 0)[Math.floor(Math.random() * 6)];
                    if (startLink) {
                        state.particles.push({
                            linkIdx: state.links.indexOf(startLink),
                            t: 0,
                            speed: 0.08
                        });
                    }
                }

                ctx.translate(cx, cy);
                ctx.rotate(time * 0.05);

                ctx.strokeStyle = 'rgba(255,255,255,0.08)';
                ctx.lineWidth = 1;
                ctx.beginPath();
                state.links.forEach((l: any) => {
                    const n1 = state.nodes[l.from];
                    const n2 = state.nodes[l.to];
                    ctx.moveTo(n1.x, n1.y);
                    ctx.lineTo(n2.x, n2.y);
                });
                ctx.stroke();

                state.nodes.forEach((n:any) => {
                    if (n.active > 0) {
                        ctx.fillStyle = color;
                        ctx.shadowBlur = 10 * n.active;
                        ctx.shadowColor = color;
                        n.active -= 0.05;
                    } else {
                        ctx.fillStyle = n.layer === 0 ? color : 'rgba(255,255,255,0.3)';
                        ctx.shadowBlur = 0;
                    }
                    const size = n.layer === 0 ? 4 : 2;
                    ctx.beginPath(); ctx.arc(n.x, n.y, size, 0, Math.PI*2); ctx.fill();
                    ctx.shadowBlur = 0;
                });

                for(let i=state.particles.length-1; i>=0; i--) {
                    const p = state.particles[i];
                    p.t += p.speed;
                    const link = state.links[p.linkIdx];
                    if (!link) { state.particles.splice(i,1); continue; }
                    const n1 = state.nodes[link.from];
                    const n2 = state.nodes[link.to];
                    const currX = n1.x + (n2.x - n1.x) * p.t;
                    const currY = n1.y + (n2.y - n1.y) * p.t;
                    ctx.fillStyle = '#fff';
                    ctx.shadowBlur = 5; ctx.shadowColor = '#fff';
                    ctx.fillRect(currX-1.5, currY-1.5, 3, 3);
                    ctx.shadowBlur = 0;
                    if (p.t >= 1) {
                        n2.active = 1;
                        if (n2.layer < 3 && Math.random() > 0.3) {
                            const nextLinks = state.links.map((l: any, idx: number) => ({...l, idx})).filter((l: any) => l.from === link.to);
                            if (nextLinks.length > 0) {
                                const nextL = nextLinks[Math.floor(Math.random() * nextLinks.length)];
                                state.particles.push({ linkIdx: nextL.idx, t: 0, speed: 0.08 });
                            }
                        }
                        state.particles.splice(i, 1);
                    }
                }
                ctx.rotate(-time * 0.05);
                ctx.translate(-cx, -cy);
            }
            else if (mode === 'swarm') {
                const beltY = h * 0.65; 
                const inputEnd = w * 0.45;
                const outputStart = w * 0.55;
                const agentX = w * 0.5;
                const agentBaseY = beltY + 40;

                const boxSize = 18;
                const speed = 1.0; 
                const animSpeed = 0.03;

                const COLORS = ['#22d3ee', '#a78bfa', '#fbbf24']; 
                const TARGET_YS = [beltY - 80, beltY - 40, beltY];

                const lastBox = state.boxes.length > 0 ? state.boxes[state.boxes.length - 1] : null;
                const safeToSpawn = !lastBox || (lastBox.x > 80); 

                if (safeToSpawn && Math.random() > 0.99) {
                    const typeIdx = Math.floor(Math.random() * 3);
                    state.boxes.push({
                        x: -20,
                        y: beltY - boxSize,
                        w: boxSize,
                        h: boxSize,
                        color: COLORS[typeIdx],
                        targetLane: typeIdx,
                        state: 'conveyor_in' 
                    });
                }

                ctx.fillStyle = 'rgba(255,255,255,0.1)';
                ctx.fillRect(0, beltY, inputEnd, 4);
                TARGET_YS.forEach(y => {
                    ctx.fillRect(outputStart, y + boxSize, w - outputStart, 4);
                });

                ctx.fillStyle = 'rgba(255,255,255,0.2)';
                const dashOffset = (time * 60) % 40; 
                for(let i=0; i<inputEnd; i+=40) {
                    const x = i + dashOffset;
                    if(x < inputEnd) ctx.fillRect(x, beltY, 4, 4);
                }
                TARGET_YS.forEach(y => {
                    for(let i=outputStart; i<w; i+=40) {
                        const x = i + dashOffset; 
                        if(x > outputStart) ctx.fillRect(x, y + boxSize, 4, 4);
                    }
                });

                const agent = state.agent;
                ctx.fillStyle = '#333';
                ctx.fillRect(agentX - 15, agentBaseY - 20, 30, 20); 

                const pivotX = agentX;
                const pivotY = agentBaseY - 20;

                let armX = pivotX;
                let armY = beltY - 60; 
                let grabberGap = 10;

                if (agent.state === 'idle') {
                    const target = state.boxes.find((b: any) => 
                        b.state === 'conveyor_in' && 
                        b.x > inputEnd - 60 && 
                        b.x < inputEnd
                    );
                    if (target) {
                        agent.state = 'reaching';
                        agent.targetBox = target;
                        agent.t = 0;
                    }
                }

                if (agent.state === 'reaching') {
                    agent.t += animSpeed;
                    const t = Math.min(1, agent.t);
                    const b = agent.targetBox;
                    if(b.x < inputEnd - 20) b.x += speed;
                    armX = pivotX + (b.x + b.w/2 - pivotX) * t;
                    armY = (pivotY - 80) + (b.y - (pivotY - 80)) * t;
                    if (t >= 1) { agent.state = 'grasping'; agent.t = 0; }
                } 
                else if (agent.state === 'grasping') {
                    agent.t += animSpeed * 2;
                    grabberGap = 10 * (1 - Math.min(1, agent.t));
                    armX = agent.targetBox.x + agent.targetBox.w/2;
                    armY = agent.targetBox.y;
                    if (agent.t >= 1) { agent.state = 'moving'; agent.targetBox.state = 'lifted'; agent.t = 0; }
                }
                else if (agent.state === 'moving') {
                    agent.t += animSpeed;
                    const t = Math.min(1, agent.t);
                    const b = agent.targetBox;
                    const targetY = TARGET_YS[b.targetLane];

                    const startX = inputEnd - 20;
                    const targetX = outputStart + 20;

                    armX = startX + (targetX - startX) * t;
                    const midY = Math.min(beltY, targetY) - 60;
                    armY = (1-t)*(1-t)*beltY + 2*(1-t)*t*midY + t*t*targetY;

                    grabberGap = 0;
                    b.x = armX - b.w/2;
                    b.y = armY;

                    if (t >= 1) { agent.state = 'releasing'; agent.t = 0; }
                }
                else if (agent.state === 'releasing') {
                    agent.t += animSpeed * 2;
                    const b = agent.targetBox;
                    armX = b.x + b.w/2;
                    armY = b.y;
                    grabberGap = 10 * Math.min(1, agent.t);

                    if (agent.t >= 1) {
                        b.state = 'conveyor_out';
                        b.y = TARGET_YS[b.targetLane];
                        agent.state = 'returning';
                        agent.targetBox = null;
                        agent.t = 0;
                    }
                }
                else if (agent.state === 'returning') {
                    agent.t += animSpeed;
                    const t = Math.min(1, agent.t);
                    const startX = outputStart + 20;
                    const startY = armY;
                    const targetX = pivotX;
                    const targetY = beltY - 60;
                    armX = startX + (targetX - startX) * t;
                    armY = startY + (targetY - startY) * t;
                    if (t >= 1) agent.state = 'idle';
                }
                else {
                    armX = pivotX + Math.sin(time * 2) * 5;
                    armY = beltY - 60 + Math.cos(time * 3) * 5;
                }

                ctx.strokeStyle = color;
                ctx.lineWidth = 2;
                ctx.beginPath();
                ctx.moveTo(pivotX, pivotY);
                const elbowX = (pivotX + armX) / 2 - 20; 
                const elbowY = Math.min(pivotY, armY) - 30;
                ctx.quadraticCurveTo(elbowX, elbowY, armX, armY);
                ctx.stroke();

                ctx.fillStyle = '#fff';
                ctx.beginPath(); ctx.arc(pivotX, pivotY, 3, 0, Math.PI*2); ctx.fill();
                ctx.beginPath(); ctx.arc(armX, armY, 3, 0, Math.PI*2); ctx.fill();

                ctx.save();
                ctx.translate(armX, armY);
                ctx.fillStyle = color;
                ctx.fillRect(-8 - grabberGap/2, -5, 4, 15);
                ctx.fillRect(4 + grabberGap/2, -5, 4, 15);
                ctx.restore();

                for (let i = state.boxes.length - 1; i >= 0; i--) {
                    const b = state.boxes[i];
                    if (b.state === 'conveyor_in') {
                        if (agent.targetBox !== b || agent.state === 'reaching') {
                             if (b.x < inputEnd - 20) b.x += speed; 
                        }
                    } else if (b.state === 'conveyor_out') {
                        b.x += speed;
                    }
                    if (b.x > w + 20) { state.boxes.splice(i, 1); continue; }

                    ctx.fillStyle = b.color;
                    ctx.strokeStyle = '#fff';
                    ctx.lineWidth = 1;
                    ctx.fillRect(b.x, b.y, b.w, b.h);
                    ctx.strokeRect(b.x, b.y, b.w, b.h);
                    ctx.fillStyle = 'rgba(0,0,0,0.3)';
                    ctx.fillRect(b.x + 2, b.y + 2, 4, 4);
                }
            }
            else if (mode === 'translation') {
                const colWidth = 140; 
                const numCols = 2; 
                const SNIPPETS = ["POST /api/v1/ingest", "{ id: '8f3a' }", "WARN: Latency", "Converting...", "0x4F3E21", "SELECT * FROM logs", "Processing...", "struct Node", "ERROR: Timeout", "> System.init()"];

                if (state.columns.length === 0) {
                    state.columns = Array.from({ length: numCols }, (_, i) => ({
                        x: 20 + i * (colWidth + 10),
                        y: Math.random() * h,
                        speed: 0.5 + Math.random() * 0.5,
                        items: Array.from({ length: 15 }, () => ({
                            text: SNIPPETS[Math.floor(Math.random() * SNIPPETS.length)],
                            y: 0 
                        }))
                    }));
                }

                const gridStartX = w * 0.55;
                const gridCols = 6; const gridRows = 8;
                const cellW = (w * 0.4) / gridCols; const cellH = h / gridRows;
                if (state.grid.length === 0) {
                    for(let i=0; i<gridCols*gridRows; i++) {
                        state.grid.push({
                            x: gridStartX + (i % gridCols) * cellW + cellW/2,
                            y: Math.floor(i / gridCols) * cellH + cellH/2,
                            filled: false, alpha: 0.2
                        });
                    }
                }

                ctx.font = '10px monospace';
                ctx.textAlign = 'left';

                state.columns.forEach((col: any) => {
                    col.y -= col.speed;
                    if (col.y < -300) col.y = h; 

                    col.items.forEach((item: any, i: number) => {
                        const yPos = col.y + i * 20;
                        const drawnY = yPos % (h + 300) - 50;

                        if (drawnY > -20 && drawnY < h + 20) {
                            const isScanned = Math.abs(drawnY - h/2) < 20;
                            ctx.fillStyle = isScanned ? '#fff' : 'rgba(255,255,255,0.3)';
                            if (isScanned) {
                                if (Math.random() > 0.98) {
                                    const empty = state.grid.filter((g: any) => !g.filled);
                                    if (empty.length > 0) {
                                        const t = empty[Math.floor(Math.random() * empty.length)];
                                        t.filled = true;
                                        state.particles.push({
                                            x: col.x + 80, y: drawnY,
                                            tx: t.x, ty: t.y,
                                            progress: 0, speed: 0.05,
                                            target: t
                                        });
                                    }
                                }
                            }
                            ctx.fillText(item.text, col.x, drawnY);
                        }
                    });
                });

                ctx.fillStyle = color;
                ctx.globalAlpha = 0.1;
                ctx.fillRect(0, h/2 - 20, w * 0.45, 40);
                ctx.globalAlpha = 0.8;
                ctx.fillRect(0, h/2, w * 0.45, 1);

                ctx.globalAlpha = 1;
                for (let i = state.particles.length - 1; i >= 0; i--) {
                    const p = state.particles[i];
                    p.progress += p.speed;
                    const t = p.progress;
                    const lx = p.x + (p.tx - p.x) * t;
                    const ly = p.y + (p.ty - p.y) * t;

                    ctx.fillStyle = color;
                    ctx.fillRect(lx - 2, ly - 2, 4, 4);

                    if (p.progress >= 1) {
                        p.target.alpha = 1.0;
                        state.particles.splice(i, 1);
                    }
                }

                state.grid.forEach((cell: any) => {
                    if (cell.filled) cell.alpha = Math.max(0.4, cell.alpha - 0.02);
                    else cell.alpha = 0.1;
                    const s = Math.min(cellW, cellH) * 0.6;
                    ctx.strokeStyle = color; ctx.globalAlpha = cell.alpha; ctx.lineWidth = 1;
                    ctx.strokeRect(cell.x - s/2, cell.y - s/2, s, s);
                    if (cell.filled) {
                        ctx.fillStyle = color; ctx.globalAlpha = cell.alpha * 0.6;
                        ctx.fillRect(cell.x - s/2 + 2, cell.y - s/2 + 2, s - 4, s - 4);
                        if (Math.random() > 0.995) cell.filled = false;
                    }
                });
            }

            ctx.globalAlpha = 1;
            frameId = requestAnimationFrame(render);
        };

        const observer = new ResizeObserver(() => { resize(); });
        observer.observe(container);
        resize();
        render();

        return () => {
            observer.disconnect();
            cancelAnimationFrame(frameId);
        };
    }, [mode, color]);

    return (
        <div ref={containerRef} className="w-full h-full relative overflow-hidden bg-[#0c0c0e]">
            <canvas ref={canvasRef} className="block absolute top-0 left-0" />
            <div className="absolute inset-0 pointer-events-none opacity-20" style={{ backgroundImage: 'linear-gradient(rgba(18, 16, 16, 0) 50%, rgba(0, 0, 0, 0.25) 50%), linear-gradient(90deg, rgba(255, 0, 0, 0.06), rgba(0, 255, 0, 0.02), rgba(0, 0, 255, 0.06))', backgroundSize: '100% 2px, 3px 100%' }} />
        </div>
    );
};

import React, { useEffect, useRef } from 'react';

interface SectionVisualizerProps {
    mode: 'search' | 'redaction' | 'logic' | 'core' | 'shield' | 'swarm' | 'predictive' | 'translation' | 'identity';
    color: string;
}

export const SectionVisualizer: React.FC<SectionVisualizerProps> = ({ mode, color }) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const containerRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const canvas = canvasRef.current;
        const container = containerRef.current;
        if (!canvas || !container) return;

        const ctx = canvas.getContext('2d', { alpha: true });
        if (!ctx) return;

        let frameId: number;
        let time = 0;

        // --- STATE MANAGEMENT ---
        const state: any = {
            width: 0,
            height: 0,
            particles: [],
            nodes: [],
            links: [], 
            grid: [],
            columns: [], 
            task: null, 
            agent: { state: 'idle', t: 0, heldBox: null, armHeight: 0, armExt: 0 },
            boxes: [], 
            stack: [],
            // Identity Mode (Learning Feed) State
            feedState: 'reading', // reading -> selecting -> feedback -> swiping
            feedTimer: 0,
            currentCardIndex: 0,
            swipeOffset: 0,
            streak: 42,
            xp: 1250,
            cursor: { x: 0, y: 0, targetX: 0, targetY: 0, clicking: false },
            feedCards: [
                { 
                    type: 'SECURITY_ALERT', 
                    bg: ['#1e1b4b', '#312e81'], // Indigo
                    author: "@SecurOps_Bot",
                    q: "Phishing Attempt Detected", 
                    sub: "Email from 'IT-Support' asks for password reset via external link.", 
                    opts: ["Click & Verify", "Report as Phishing"], 
                    correct: 1, 
                    likes: "12.4k",
                    comments: "402"
                },
                { 
                    type: 'SAFETY_PROTOCOL', 
                    bg: ['#451a03', '#78350f'], // Amber
                    author: "@SiteSafety_Lead",
                    q: "Forklift Zone Violation", 
                    sub: "Pedestrian observed in yellow zone while lift is active.", 
                    opts: ["Sound Alarm", "Ignore"], 
                    correct: 0, 
                    likes: "8.2k",
                    comments: "156"
                },
                { 
                    type: 'DATA_PRIVACY', 
                    bg: ['#022c22', '#115e59'], // Emerald
                    author: "@Compliance_AI",
                    q: "PII in Ticket Comments", 
                    sub: "Customer posted credit card info in support chat.", 
                    opts: ["Leave it", "Redact Immediately"], 
                    correct: 1, 
                    likes: "45k",
                    comments: "2.1k"
                },
                { 
                    type: 'ETHICS_CHECK', 
                    bg: ['#4c0519', '#9f1239'], // Rose
                    author: "@HR_Partner",
                    q: "Vendor Gift Policy", 
                    sub: "Supplier offers front-row tickets worth $500.", 
                    opts: ["Decline Gift", "Accept Gift"], 
                    correct: 0, 
                    likes: "3.1k",
                    comments: "89"
                }
            ],
            // Logic/Strategy Mode State
            packets: [],
            initializedMode: null
        };

        const resize = () => {
            const rect = container.getBoundingClientRect();
            const dpr = window.devicePixelRatio || 1;

            canvas.width = rect.width * dpr;
            canvas.height = rect.height * dpr;

            canvas.style.width = `${rect.width}px`;
            canvas.style.height = `${rect.height}px`;

            ctx.scale(dpr, dpr);

            state.width = rect.width;
            state.height = rect.height;

            if (mode !== state.initializedMode) {
                init(rect.width, rect.height);
            }
        };

        const init = (w: number, h: number) => {
            state.particles = [];
            state.nodes = [];
            state.links = [];
            state.grid = [];
            state.columns = [];
            state.task = null;
            state.boxes = [];
            state.stack = [];
            state.packets = [];
            state.agent = { state: 'idle', t: 0, heldBox: null, armHeight: 0, armExt: 0 };

            // Identity specific
            state.feedState = 'reading';
            state.feedTimer = 0;
            state.currentCardIndex = 0;
            state.swipeOffset = 0;
            state.cursor = { x: w/2, y: h*0.8, targetX: w/2, targetY: h*0.8, clicking: false };

            state.initializedMode = mode;

            if (mode === 'search') {
                const particleCount = 80;
                for(let i=0; i<particleCount; i++) {
                    state.particles.push({
                        x: Math.random() * w,
                        y: Math.random() * h,
                        vx: 2 + Math.random() * 1.5,
                        vy: (Math.random() - 0.5) * 0.5,
                        targetLane: Math.floor(Math.random() * 5),
                        size: 0.5 + Math.random() * 0.5
                    });
                }
            }
            else if (mode === 'logic') {
                // STRATEGY BUILDER
                state.nodes.push({ id: 0, x: w * 0.15, y: h * 0.3, label: "DEMAND SPIKE", type: 'trigger', active: 0 });
                state.nodes.push({ id: 1, x: w * 0.15, y: h * 0.7, label: "INVENTORY LOW", type: 'trigger', active: 0 });
                state.nodes.push({ id: 2, x: w * 0.45, y: h * 0.5, label: "ALLOCATION LOGIC", type: 'process', active: 0 });
                state.nodes.push({ id: 3, x: w * 0.75, y: h * 0.25, label: "PRIORITY: RETAIL", type: 'action', active: 0 });
                state.nodes.push({ id: 4, x: w * 0.75, y: h * 0.75, label: "LIMIT WHOLESALE", type: 'action', active: 0 });
                state.links.push({ from: 0, to: 2 });
                state.links.push({ from: 1, to: 2 });
                state.links.push({ from: 2, to: 3 });
                state.links.push({ from: 2, to: 4 });
            }
        };

        const render = () => {
            time += 0.01;
            const w = state.width;
            const h = state.height;
            const cx = w/2;
            const cy = h/2;

            ctx.clearRect(0, 0, w, h);

            if (mode === 'identity') {
                // --- "SkillStream": Corporate Learning Feed ---

                // 1. UPDATE STATE & PHYSICS
                state.feedTimer++;
                const card = state.feedCards[state.currentCardIndex];

                // -- Cursor Simulation Logic --
                if (state.feedState === 'reading') {
                    // Idle hover
                    state.cursor.targetX = w/2 + Math.sin(time) * 30;
                    state.cursor.targetY = h * 0.7 + Math.cos(time * 1.5) * 30;

                    if (state.feedTimer > 100) { 
                        state.feedState = 'selecting';
                    }
                } 
                else if (state.feedState === 'selecting') {
                    // Move to correct button
                    const btnH = 50;
                    const spacing = 15;
                    const btnY = h * 0.65 + card.correct * (btnH + spacing) + btnH/2;

                    state.cursor.targetX = w/2;
                    state.cursor.targetY = btnY;

                    // Snap click when close
                    const dx = state.cursor.targetX - state.cursor.x;
                    const dy = state.cursor.targetY - state.cursor.y;
                    if (Math.sqrt(dx*dx + dy*dy) < 5) {
                        state.cursor.clicking = true;
                        state.feedState = 'feedback';
                        state.feedTimer = 0;
                        state.streak++;
                        state.xp += 150;

                        // Explosion
                        for(let i=0; i<40; i++) {
                            state.particles.push({
                                x: state.cursor.x,
                                y: state.cursor.y,
                                vx: (Math.random()-0.5) * 15,
                                vy: (Math.random()-0.5) * 15 - 5,
                                life: 1.0,
                                color: ['#4ade80', '#fbbf24', '#ffffff'][Math.floor(Math.random()*3)]
                            });
                        }
                    }
                }
                else if (state.feedState === 'feedback') {
                    state.cursor.clicking = false;
                    if (state.feedTimer > 60) { 
                        state.feedState = 'swiping';
                        state.cursor.targetY = h * 0.2; // Move up to swipe
                        state.feedTimer = 0;
                    }
                }
                else if (state.feedState === 'swiping') {
                    // Lerp Offset
                    state.swipeOffset += (-h - state.swipeOffset) * 0.15;

                    // Reset
                    if (Math.abs(state.swipeOffset + h) < 5) {
                        state.currentCardIndex = (state.currentCardIndex + 1) % state.feedCards.length;
                        state.swipeOffset = 0;
                        state.feedState = 'reading';
                        state.feedTimer = 0;
                        state.cursor.y = h + 100; // Reset cursor pos
                    }
                }

                // Cursor Physics
                state.cursor.x += (state.cursor.targetX - state.cursor.x) * 0.15;
                state.cursor.y += (state.cursor.targetY - state.cursor.y) * 0.15;

                // -- RENDER --

                ctx.save();
                ctx.translate(0, state.swipeOffset);

                // 1. Dynamic Video Background (Simulated)
                const grad = ctx.createLinearGradient(0, 0, 0, h);
                grad.addColorStop(0, card.bg[0]);
                grad.addColorStop(1, card.bg[1]);
                ctx.fillStyle = grad;
                ctx.fillRect(0, 0, w, h);

                // Animated Abstract Blobs (The "Content")
                ctx.save();
                ctx.globalAlpha = 0.2;
                ctx.fillStyle = '#fff';
                for(let i=0; i<3; i++) {
                    const bx = (Math.sin(time + i) * 100 + w/2);
                    const by = (Math.cos(time * 0.5 + i) * 100 + h/2);
                    ctx.beginPath(); ctx.arc(bx, by, 80 + i*20, 0, Math.PI*2); ctx.fill();
                }
                ctx.restore();

                // 2. Right Sidebar (Social Actions)
                const rightMargin = w - 40;
                const bottomMargin = h - 100;

                // Avatar
                ctx.beginPath(); ctx.arc(rightMargin, bottomMargin - 160, 18, 0, Math.PI*2); 
                ctx.fillStyle = '#fff'; ctx.fill();
                ctx.lineWidth = 2; ctx.strokeStyle = '#22c55e'; ctx.stroke();

                // Heart
                ctx.fillStyle = state.feedState === 'feedback' ? '#ef4444' : 'rgba(255,255,255,0.8)';
                ctx.font = '24px serif'; ctx.textAlign='center'; ctx.fillText('♥', rightMargin, bottomMargin - 100);
                ctx.font = '10px sans-serif'; ctx.fillStyle='#fff'; ctx.fillText(card.likes, rightMargin, bottomMargin - 85);

                // Comment
                ctx.fillStyle = 'rgba(255,255,255,0.8)';
                ctx.font = '24px serif'; ctx.fillText('💬', rightMargin, bottomMargin - 40);
                ctx.font = '10px sans-serif'; ctx.fillStyle='#fff'; ctx.fillText(card.comments, rightMargin, bottomMargin - 25);

                // 3. Bottom Content Overlay
                ctx.textAlign = 'left';

                // Author Tag
                ctx.font = 'bold 12px sans-serif'; ctx.fillStyle = '#fff';
                ctx.fillText(card.author, 20, h * 0.42);

                // Question
                ctx.font = 'bold 18px sans-serif'; 
                ctx.shadowColor="rgba(0,0,0,0.5)"; ctx.shadowBlur=4;
                ctx.fillText(card.q, 20, h * 0.42 + 25);
                ctx.shadowBlur=0;

                // Subtext
                ctx.font = '12px sans-serif'; ctx.fillStyle = 'rgba(255,255,255,0.8)';
                const subWidth = ctx.measureText(card.sub).width;
                if (subWidth > w - 80) {
                    ctx.fillText(card.sub.substring(0, 30) + "...", 20, h * 0.42 + 45);
                } else {
                    ctx.fillText(card.sub, 20, h * 0.42 + 45);
                }

                // 4. Interactive Options
                card.opts.forEach((opt: string, i: number) => {
                    const btnH = 50;
                    const spacing = 15;
                    const btnW = w * 0.75;
                    const btnX = (w - btnW) / 2;
                    const btnY = h * 0.65 + i * (btnH + spacing);

                    const isCorrect = i === card.correct;
                    const isSelected = (state.feedState === 'feedback' || state.feedState === 'swiping') && isCorrect;

                    // Glassmorphism Button
                    ctx.fillStyle = isSelected ? '#22c55e' : 'rgba(255,255,255,0.15)';
                    if (isSelected) {
                        ctx.shadowColor = '#22c55e'; ctx.shadowBlur = 20;
                    } else {
                        ctx.shadowColor = 'transparent'; ctx.shadowBlur = 0;
                    }

                    ctx.beginPath(); ctx.roundRect(btnX, btnY, btnW, btnH, 12); ctx.fill();

                    // Text
                    ctx.fillStyle = '#fff'; ctx.font = 'bold 13px sans-serif'; ctx.textAlign = 'center';
                    ctx.fillText(opt, w/2, btnY + 30);

                    // Reset Shadow
                    ctx.shadowBlur = 0;
                });

                // 5. Success Feedback Banner
                if (state.feedState === 'feedback' || state.feedState === 'swiping') {
                    const bannerY = state.feedState === 'feedback' ? 
                        h - 80 - Math.min(1, state.feedTimer/10) * 20 : // Pop up
                        h - 100 + state.feedTimer; // Slide down

                    ctx.fillStyle = '#22c55e';
                    ctx.fillRect(0, bannerY, w, 150);

                    ctx.fillStyle = '#fff';
                    ctx.font = 'bold 20px sans-serif'; ctx.textAlign = 'left';
                    ctx.fillText("Nice work!", 20, bannerY + 40);
                    ctx.font = '12px sans-serif';
                    ctx.fillText(`Streak: ${state.streak} 🔥  XP: ${state.xp}`, 20, bannerY + 65);
                }

                // 6. Particles
                for (let i = state.particles.length - 1; i >= 0; i--) {
                    const p = state.particles[i];
                    p.x += p.vx;
                    p.y += p.vy;
                    p.vy += 0.8; // Gravity
                    p.life -= 0.02;

                    if (p.life <= 0) {
                        state.particles.splice(i, 1);
                        continue;
                    }

                    ctx.fillStyle = p.color;
                    ctx.globalAlpha = p.life;
                    ctx.fillRect(p.x, p.y, 5, 5); 
                }
                ctx.globalAlpha = 1;

                // 7. Header UI
                ctx.fillStyle = 'rgba(0,0,0,0.3)';
                ctx.fillRect(0, 0, w, 60);

                // Progress Segmented
                const totalCards = state.feedCards.length;
                const segW = (w - 40 - (totalCards-1)*5) / totalCards;
                for(let i=0; i<totalCards; i++) {
                    ctx.fillStyle = i <= state.currentCardIndex ? '#fff' : 'rgba(255,255,255,0.2)';
                    ctx.fillRect(20 + i*(segW+5), 20, segW, 4);
                }

                ctx.restore(); // End Translate

                // 8. Simulated Cursor Overlay
                if (state.feedState !== 'swiping') {
                    ctx.shadowBlur = 10; ctx.shadowColor = 'rgba(0,0,0,0.5)';
                    ctx.fillStyle = '#fff';
                    // Arrow cursor
                    ctx.beginPath();
                    ctx.moveTo(state.cursor.x, state.cursor.y);
                    ctx.lineTo(state.cursor.x + 12, state.cursor.y + 12);
                    ctx.lineTo(state.cursor.x + 5, state.cursor.y + 12);
                    ctx.lineTo(state.cursor.x, state.cursor.y + 18);
                    ctx.closePath();
                    ctx.fill();

                    // Click Ripple
                    if (state.cursor.clicking) {
                        ctx.strokeStyle = 'rgba(255,255,255,0.8)';
                        ctx.lineWidth = 2;
                        ctx.beginPath(); ctx.arc(state.cursor.x, state.cursor.y, 20, 0, Math.PI*2); ctx.stroke();
                    }
                    ctx.shadowBlur = 0;
                }
            }
            // ... (Existing logic for other modes)
            else if (mode === 'search') {
                const processLine = w * 0.4;
                const laneCount = 5;
                const laneHeight = h / laneCount;

                ctx.lineWidth = 1;
                ctx.strokeStyle = 'rgba(255, 255, 255, 0.08)';
                for(let i=0; i<laneCount; i++) {
                    const ly = i * laneHeight + laneHeight/2;
                    ctx.beginPath(); ctx.moveTo(processLine, ly); ctx.lineTo(w, ly); ctx.stroke();
                }

                const scannerGlow = ctx.createLinearGradient(processLine, 0, processLine + 60, 0);
                scannerGlow.addColorStop(0, color);
                scannerGlow.addColorStop(1, 'transparent');
                ctx.fillStyle = scannerGlow;
                ctx.globalAlpha = 0.15;
                ctx.fillRect(processLine, 0, 60, h);

                ctx.fillStyle = color;
                ctx.globalAlpha = 0.8;
                ctx.fillRect(processLine, 0, 2, h);

                state.particles.forEach((p: any) => {
                    p.x += p.vx;
                    if (p.x < processLine) {
                        p.y += p.vy;
                        if (p.y < 0) p.y += h;
                        if (p.y > h) p.y -= h;
                        ctx.fillStyle = 'rgba(255, 255, 255, 0.4)';
                        ctx.globalAlpha = 0.6;
                        ctx.beginPath(); ctx.arc(p.x, p.y, p.size * 2, 0, Math.PI*2); ctx.fill();
                    } else {
                        const targetY = p.targetLane * laneHeight + laneHeight/2;
                        p.y += (targetY - p.y) * 0.15; 
                        p.x += 1.5; 
                        ctx.fillStyle = color;
                        ctx.globalAlpha = 1;
                        const packetWidth = 20 * p.size;
                        const packetHeight = 4;
                        ctx.shadowColor = color; ctx.shadowBlur = 10;
                        ctx.fillRect(p.x, p.y - packetHeight/2, packetWidth, packetHeight);
                        ctx.shadowBlur = 0;
                    }
                    if (p.x > w + 50) {
                        p.x = -20;
                        p.y = Math.random() * h;
                        p.vx = 2 + Math.random() * 1.5;
                        p.targetLane = Math.floor(Math.random() * laneCount);
                    }
                });
            }
            else if (mode === 'redaction') {
                const scanY = (time * 100) % (h + 100) - 50;
                state.particles.forEach((p: any) => {
                    const dist = Math.abs(p.y - scanY);
                    if (dist < 50) {
                        ctx.fillStyle = color;
                        ctx.globalAlpha = 1 - (dist/50);
                        ctx.fillRect(p.x, p.y, p.w, p.h);
                    } else {
                        ctx.fillStyle = 'rgba(255,255,255,0.05)';
                        ctx.globalAlpha = 1;
                        ctx.fillRect(p.x, p.y, p.w, p.h);
                    }
                });
                ctx.fillStyle = '#fff';
                ctx.fillRect(0, scanY, w, 2);
            }
            else if (mode === 'logic') {
                // Spawn Packets
                if (Math.random() > 0.98) {
                    const startNodes = state.nodes.filter((n: any) => n.type === 'trigger');
                    const start = startNodes[Math.floor(Math.random() * startNodes.length)];
                    state.nodes.forEach((n: any) => { if(n.id === start.id) n.active = 1.0; });

                    // Find links from this start
                    const links = state.links.filter((l: any) => l.from === start.id);
                    links.forEach((l: any) => {
                        state.packets.push({
                            fromId: l.from, toId: l.to, progress: 0, speed: 0.02 + Math.random() * 0.01
                        });
                    });
                }

                // Draw Links
                ctx.lineWidth = 2;
                state.links.forEach((l: any) => {
                    const n1 = state.nodes.find((n: any) => n.id === l.from);
                    const n2 = state.nodes.find((n: any) => n.id === l.to);

                    const grad = ctx.createLinearGradient(n1.x, n1.y, n2.x, n2.y);
                    grad.addColorStop(0, 'rgba(255,255,255,0.1)');
                    grad.addColorStop(1, 'rgba(255,255,255,0.05)');
                    ctx.strokeStyle = grad;

                    ctx.beginPath();
                    ctx.moveTo(n1.x, n1.y);
                    const midX = (n1.x + n2.x) / 2;
                    ctx.bezierCurveTo(midX, n1.y, midX, n2.y, n2.x, n2.y);
                    ctx.stroke();
                });

                // Draw Packets
                for (let i = state.packets.length - 1; i >= 0; i--) {
                    const p = state.packets[i];
                    p.progress += p.speed;

                    const n1 = state.nodes.find((n: any) => n.id === p.fromId);
                    const n2 = state.nodes.find((n: any) => n.id === p.toId);

                    const midX = (n1.x + n2.x) / 2;
                    const t = p.progress;
                    const invT = 1 - t;

                    const x = invT*invT*invT*n1.x + 3*invT*invT*t*midX + 3*invT*t*t*midX + t*t*t*n2.x;
                    const y = invT*invT*invT*n1.y + 3*invT*invT*t*n1.y + 3*invT*t*t*n2.y + t*t*t*n2.y;

                    ctx.fillStyle = color;
                    ctx.shadowBlur = 10; ctx.shadowColor = color;
                    ctx.beginPath(); ctx.arc(x, y, 3, 0, Math.PI*2); ctx.fill();
                    ctx.shadowBlur = 0;

                    if (p.progress >= 1) {
                        n2.active = 1.0;
                        const nextLinks = state.links.filter((l: any) => l.from === n2.id);
                        nextLinks.forEach((l: any) => {
                            state.packets.push({ fromId: l.from, toId: l.to, progress: 0, speed: 0.02 });
                        });
                        state.packets.splice(i, 1);
                    }
                }

                // Draw Nodes
                state.nodes.forEach((n: any) => {
                    const isActive = n.active > 0.01;
                    if (n.active > 0) n.active *= 0.95;

                    ctx.save();
                    ctx.translate(n.x, n.y);

                    if (n.type === 'trigger') {
                        ctx.fillStyle = isActive ? color : '#1a1a1c';
                        ctx.strokeStyle = isActive ? '#fff' : 'rgba(255,255,255,0.2)';
                        ctx.beginPath(); ctx.moveTo(0, -20); ctx.lineTo(20, 0); ctx.lineTo(0, 20); ctx.lineTo(-20, 0); ctx.closePath();
                    } else if (n.type === 'process') {
                        ctx.fillStyle = isActive ? color : '#1a1a1c';
                        ctx.strokeStyle = isActive ? '#fff' : 'rgba(255,255,255,0.2)';
                        ctx.beginPath(); ctx.roundRect(-40, -20, 80, 40, 4);
                    } else {
                        ctx.fillStyle = isActive ? color : '#1a1a1c';
                        ctx.strokeStyle = isActive ? '#fff' : 'rgba(255,255,255,0.2)';
                        ctx.beginPath(); ctx.roundRect(-30, -15, 60, 30, 15);
                    }

                    ctx.globalAlpha = isActive ? 0.8 : 0.5;
                    ctx.fill();
                    ctx.globalAlpha = 1;
                    ctx.lineWidth = 1;
                    ctx.stroke();

                    ctx.fillStyle = '#fff';
                    ctx.font = '9px monospace';
                    ctx.textAlign = 'center';
                    ctx.textBaseline = 'middle';

                    const textW = ctx.measureText(n.label).width;
                    ctx.fillStyle = 'rgba(0,0,0,0.6)';
                    ctx.fillRect(-textW/2 - 4, 22, textW + 8, 14);
                    ctx.fillStyle = isActive ? color : '#888';
                    ctx.fillText(n.label, 0, 29);

                    ctx.restore();
                });
            }
            // ... (Other modes omitted for brevity, logic remains in 'render')
        };

        const observer = new ResizeObserver(() => { resize(); });
        observer.observe(container);
        resize();
        render();

        return () => {
            observer.disconnect();
            cancelAnimationFrame(frameId);
        };
    }, [mode, color]);

    return (
        <div ref={containerRef} className="w-full h-full relative overflow-hidden bg-[#0c0c0e]">
            <canvas ref={canvasRef} className="block absolute top-0 left-0" />
            <div className="absolute inset-0 pointer-events-none opacity-20" style={{ backgroundImage: 'linear-gradient(rgba(18, 16, 16, 0) 50%, rgba(0, 0, 0, 0.25) 50%), linear-gradient(90deg, rgba(255, 0, 0, 0.06), rgba(0, 255, 0, 0.02), rgba(0, 0, 255, 0.06))', backgroundSize: '100% 2px, 3px 100%' }} />
        </div>
    );
};

import React, { useEffect, useRef } from 'react';

interface SectionVisualizerProps {
    mode: 'search' | 'redaction' | 'logic' | 'core' | 'shield' | 'swarm' | 'predictive' | 'translation' | 'identity';
    color: string;
}

export const SectionVisualizer: React.FC<SectionVisualizerProps> = ({ mode, color }) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const containerRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const canvas = canvasRef.current;
        const container = containerRef.current;
        if (!canvas || !container) return;

        const ctx = canvas.getContext('2d', { alpha: true });
        if (!ctx) return;

        let frameId: number;
        let time = 0;

        // --- STATE MANAGEMENT ---
        const state: any = {
            width: 0,
            height: 0,
            particles: [],
            nodes: [],
            links: [], 
            grid: [],
            columns: [], 
            task: null, 
            agent: { state: 'idle', t: 0, heldBox: null, armHeight: 0, armExt: 0 },
            boxes: [], 
            stack: [],
            // Identity Mode (Learning Feed) State
            feedState: 'reading', // reading -> selecting -> feedback -> swiping
            feedTimer: 0,
            currentCardIndex: 0,
            swipeOffset: 0,
            streak: 42,
            xp: 1250,
            cursor: { x: 0, y: 0, targetX: 0, targetY: 0, clicking: false },
            feedCards: [
                { 
                    type: 'SECURITY_ALERT', 
                    bg: ['#1e1b4b', '#312e81'], // Indigo
                    author: "@SecurOps_Bot",
                    q: "Phishing Attempt Detected", 
                    sub: "Email from 'IT-Support' asks for password reset via external link.", 
                    opts: ["Click & Verify", "Report as Phishing"], 
                    correct: 1, 
                    likes: "12.4k",
                    comments: "402"
                },
                { 
                    type: 'SAFETY_PROTOCOL', 
                    bg: ['#451a03', '#78350f'], // Amber
                    author: "@SiteSafety_Lead",
                    q: "Forklift Zone Violation", 
                    sub: "Pedestrian observed in yellow zone while lift is active.", 
                    opts: ["Sound Alarm", "Ignore"], 
                    correct: 0, 
                    likes: "8.2k",
                    comments: "156"
                },
                { 
                    type: 'DATA_PRIVACY', 
                    bg: ['#022c22', '#115e59'], // Emerald
                    author: "@Compliance_AI",
                    q: "PII in Ticket Comments", 
                    sub: "Customer posted credit card info in support chat.", 
                    opts: ["Leave it", "Redact Immediately"], 
                    correct: 1, 
                    likes: "45k",
                    comments: "2.1k"
                },
                { 
                    type: 'ETHICS_CHECK', 
                    bg: ['#4c0519', '#9f1239'], // Rose
                    author: "@HR_Partner",
                    q: "Vendor Gift Policy", 
                    sub: "Supplier offers front-row tickets worth $500.", 
                    opts: ["Decline Gift", "Accept Gift"], 
                    correct: 0, 
                    likes: "3.1k",
                    comments: "89"
                }
            ],
            // Logic/Strategy Mode State
            packets: [],
            initializedMode: null
        };

        const resize = () => {
            const rect = container.getBoundingClientRect();
            const dpr = window.devicePixelRatio || 1;

            canvas.width = rect.width * dpr;
            canvas.height = rect.height * dpr;

            canvas.style.width = `${rect.width}px`;
            canvas.style.height = `${rect.height}px`;

            ctx.scale(dpr, dpr);

            state.width = rect.width;
            state.height = rect.height;

            if (mode !== state.initializedMode) {
                init(rect.width, rect.height);
            }
        };

        const init = (w: number, h: number) => {
            state.particles = [];
            state.nodes = [];
            state.links = [];
            state.grid = [];
            state.columns = [];
            state.task = null;
            state.boxes = [];
            state.stack = [];
            state.packets = [];
            state.agent = { state: 'idle', t: 0, heldBox: null, armHeight: 0, armExt: 0 };

            // Identity specific
            state.feedState = 'reading';
            state.feedTimer = 0;
            state.currentCardIndex = 0;
            state.swipeOffset = 0;
            state.cursor = { x: w/2, y: h*0.8, targetX: w/2, targetY: h*0.8, clicking: false };

            state.initializedMode = mode;

            if (mode === 'search') {
                const particleCount = 80;
                for(let i=0; i<particleCount; i++) {
                    state.particles.push({
                        x: Math.random() * w,
                        y: Math.random() * h,
                        vx: 2 + Math.random() * 1.5,
                        vy: (Math.random() - 0.5) * 0.5,
                        targetLane: Math.floor(Math.random() * 5),
                        size: 0.5 + Math.random() * 0.5
                    });
                }
            }
            else if (mode === 'logic') {
                // STRATEGY BUILDER
                state.nodes.push({ id: 0, x: w * 0.15, y: h * 0.3, label: "DEMAND SPIKE", type: 'trigger', active: 0 });
                state.nodes.push({ id: 1, x: w * 0.15, y: h * 0.7, label: "INVENTORY LOW", type: 'trigger', active: 0 });
                state.nodes.push({ id: 2, x: w * 0.45, y: h * 0.5, label: "ALLOCATION LOGIC", type: 'process', active: 0 });
                state.nodes.push({ id: 3, x: w * 0.75, y: h * 0.25, label: "PRIORITY: RETAIL", type: 'action', active: 0 });
                state.nodes.push({ id: 4, x: w * 0.75, y: h * 0.75, label: "LIMIT WHOLESALE", type: 'action', active: 0 });
                state.links.push({ from: 0, to: 2 });
                state.links.push({ from: 1, to: 2 });
                state.links.push({ from: 2, to: 3 });
                state.links.push({ from: 2, to: 4 });
            }
        };

        const render = () => {
            time += 0.01;
            const w = state.width;
            const h = state.height;
            const cx = w/2;
            const cy = h/2;

            ctx.clearRect(0, 0, w, h);

            if (mode === 'identity') {
                // --- "SkillStream": Corporate Learning Feed ---

                // 1. UPDATE STATE & PHYSICS
                state.feedTimer++;
                const card = state.feedCards[state.currentCardIndex];

                // -- Cursor Simulation Logic --
                if (state.feedState === 'reading') {
                    // Idle hover
                    state.cursor.targetX = w/2 + Math.sin(time) * 30;
                    state.cursor.targetY = h * 0.7 + Math.cos(time * 1.5) * 30;

                    if (state.feedTimer > 100) { 
                        state.feedState = 'selecting';
                    }
                } 
                else if (state.feedState === 'selecting') {
                    // Move to correct button
                    const btnH = 50;
                    const spacing = 15;
                    const btnY = h * 0.65 + card.correct * (btnH + spacing) + btnH/2;

                    state.cursor.targetX = w/2;
                    state.cursor.targetY = btnY;

                    // Snap click when close
                    const dx = state.cursor.targetX - state.cursor.x;
                    const dy = state.cursor.targetY - state.cursor.y;
                    if (Math.sqrt(dx*dx + dy*dy) < 5) {
                        state.cursor.clicking = true;
                        state.feedState = 'feedback';
                        state.feedTimer = 0;
                        state.streak++;
                        state.xp += 150;

                        // Explosion
                        for(let i=0; i<40; i++) {
                            state.particles.push({
                                x: state.cursor.x,
                                y: state.cursor.y,
                                vx: (Math.random()-0.5) * 15,
                                vy: (Math.random()-0.5) * 15 - 5,
                                life: 1.0,
                                color: ['#4ade80', '#fbbf24', '#ffffff'][Math.floor(Math.random()*3)]
                            });
                        }
                    }
                }
                else if (state.feedState === 'feedback') {
                    state.cursor.clicking = false;
                    if (state.feedTimer > 60) { 
                        state.feedState = 'swiping';
                        state.cursor.targetY = h * 0.2; // Move up to swipe
                        state.feedTimer = 0;
                    }
                }
                else if (state.feedState === 'swiping') {
                    // Lerp Offset
                    state.swipeOffset += (-h - state.swipeOffset) * 0.15;

                    // Reset
                    if (Math.abs(state.swipeOffset + h) < 5) {
                        state.currentCardIndex = (state.currentCardIndex + 1) % state.feedCards.length;
                        state.swipeOffset = 0;
                        state.feedState = 'reading';
                        state.feedTimer = 0;
                        state.cursor.y = h + 100; // Reset cursor pos
                    }
                }

                // Cursor Physics
                state.cursor.x += (state.cursor.targetX - state.cursor.x) * 0.15;
                state.cursor.y += (state.cursor.targetY - state.cursor.y) * 0.15;

                // -- RENDER --

                ctx.save();
                ctx.translate(0, state.swipeOffset);

                // 1. Dynamic Video Background (Simulated)
                const grad = ctx.createLinearGradient(0, 0, 0, h);
                grad.addColorStop(0, card.bg[0]);
                grad.addColorStop(1, card.bg[1]);
                ctx.fillStyle = grad;
                ctx.fillRect(0, 0, w, h);

                // Animated Abstract Blobs (The "Content")
                ctx.save();
                ctx.globalAlpha = 0.2;
                ctx.fillStyle = '#fff';
                for(let i=0; i<3; i++) {
                    const bx = (Math.sin(time + i) * 100 + w/2);
                    const by = (Math.cos(time * 0.5 + i) * 100 + h/2);
                    ctx.beginPath(); ctx.arc(bx, by, 80 + i*20, 0, Math.PI*2); ctx.fill();
                }
                ctx.restore();

                // 2. Right Sidebar (Social Actions)
                const rightMargin = w - 40;
                const bottomMargin = h - 100;

                // Avatar
                ctx.beginPath(); ctx.arc(rightMargin, bottomMargin - 160, 18, 0, Math.PI*2); 
                ctx.fillStyle = '#fff'; ctx.fill();
                ctx.lineWidth = 2; ctx.strokeStyle = '#22c55e'; ctx.stroke();

                // Heart
                ctx.fillStyle = state.feedState === 'feedback' ? '#ef4444' : 'rgba(255,255,255,0.8)';
                ctx.font = '24px serif'; ctx.textAlign='center'; ctx.fillText('♥', rightMargin, bottomMargin - 100);
                ctx.font = '10px sans-serif'; ctx.fillStyle='#fff'; ctx.fillText(card.likes, rightMargin, bottomMargin - 85);

                // Comment
                ctx.fillStyle = 'rgba(255,255,255,0.8)';
                ctx.font = '24px serif'; ctx.fillText('💬', rightMargin, bottomMargin - 40);
                ctx.font = '10px sans-serif'; ctx.fillStyle='#fff'; ctx.fillText(card.comments, rightMargin, bottomMargin - 25);

                // 3. Bottom Content Overlay
                ctx.textAlign = 'left';

                // Author Tag
                ctx.font = 'bold 12px sans-serif'; ctx.fillStyle = '#fff';
                ctx.fillText(card.author, 20, h * 0.42);

                // Question
                ctx.font = 'bold 18px sans-serif'; 
                ctx.shadowColor="rgba(0,0,0,0.5)"; ctx.shadowBlur=4;
                ctx.fillText(card.q, 20, h * 0.42 + 25);
                ctx.shadowBlur=0;

                // Subtext
                ctx.font = '12px sans-serif'; ctx.fillStyle = 'rgba(255,255,255,0.8)';
                const subWidth = ctx.measureText(card.sub).width;
                if (subWidth > w - 80) {
                    ctx.fillText(card.sub.substring(0, 30) + "...", 20, h * 0.42 + 45);
                } else {
                    ctx.fillText(card.sub, 20, h * 0.42 + 45);
                }

                // 4. Interactive Options
                card.opts.forEach((opt: string, i: number) => {
                    const btnH = 50;
                    const spacing = 15;
                    const btnW = w * 0.75;
                    const btnX = (w - btnW) / 2;
                    const btnY = h * 0.65 + i * (btnH + spacing);

                    const isCorrect = i === card.correct;
                    const isSelected = (state.feedState === 'feedback' || state.feedState === 'swiping') && isCorrect;

                    // Glassmorphism Button
                    ctx.fillStyle = isSelected ? '#22c55e' : 'rgba(255,255,255,0.15)';
                    if (isSelected) {
                        ctx.shadowColor = '#22c55e'; ctx.shadowBlur = 20;
                    } else {
                        ctx.shadowColor = 'transparent'; ctx.shadowBlur = 0;
                    }

                    ctx.beginPath(); ctx.roundRect(btnX, btnY, btnW, btnH, 12); ctx.fill();

                    // Text
                    ctx.fillStyle = '#fff'; ctx.font = 'bold 13px sans-serif'; ctx.textAlign = 'center';
                    ctx.fillText(opt, w/2, btnY + 30);

                    // Reset Shadow
                    ctx.shadowBlur = 0;
                });

                // 5. Success Feedback Banner
                if (state.feedState === 'feedback' || state.feedState === 'swiping') {
                    const bannerY = state.feedState === 'feedback' ? 
                        h - 80 - Math.min(1, state.feedTimer/10) * 20 : // Pop up
                        h - 100 + state.feedTimer; // Slide down

                    ctx.fillStyle = '#22c55e';
                    ctx.fillRect(0, bannerY, w, 150);

                    ctx.fillStyle = '#fff';
                    ctx.font = 'bold 20px sans-serif'; ctx.textAlign = 'left';
                    ctx.fillText("Nice work!", 20, bannerY + 40);
                    ctx.font = '12px sans-serif';
                    ctx.fillText(`Streak: ${state.streak} 🔥  XP: ${state.xp}`, 20, bannerY + 65);
                }

                // 6. Particles
                for (let i = state.particles.length - 1; i >= 0; i--) {
                    const p = state.particles[i];
                    p.x += p.vx;
                    p.y += p.vy;
                    p.vy += 0.8; // Gravity
                    p.life -= 0.02;

                    if (p.life <= 0) {
                        state.particles.splice(i, 1);
                        continue;
                    }

                    ctx.fillStyle = p.color;
                    ctx.globalAlpha = p.life;
                    ctx.fillRect(p.x, p.y, 5, 5); 
                }
                ctx.globalAlpha = 1;

                // 7. Header UI (Progress Bar)
                const totalCards = state.feedCards.length;
                const segW = (w - 40 - (totalCards-1)*5) / totalCards;
                for(let i=0; i<totalCards; i++) {
                    ctx.fillStyle = i <= state.currentCardIndex ? '#fff' : 'rgba(255,255,255,0.2)';
                    ctx.fillRect(20 + i*(segW+5), 20, segW, 4);
                }

                ctx.restore(); // End Translate

                // --- NEW: Suspended Pill Cutout (Dynamic Island) ---
                ctx.save();
                const pillW = 100;
                const pillH = 30;
                const pillY = h * 0.05; 
                const pillX = w/2 - pillW/2;

                ctx.shadowColor = 'rgba(0,0,0,0.8)';
                ctx.shadowBlur = 15;
                ctx.shadowOffsetY = 5;

                ctx.fillStyle = '#000';
                ctx.beginPath();
                ctx.roundRect(pillX, pillY, pillW, pillH, 50);
                ctx.fill();
                ctx.shadowBlur = 0; 

                // FaceID / Camera sensor details
                ctx.fillStyle = '#1a1a1a';
                ctx.beginPath();
                ctx.arc(pillX + pillW - 25, pillY + pillH/2, 8, 0, Math.PI*2);
                ctx.fill();

                ctx.fillStyle = '#080808';
                ctx.beginPath();
                ctx.arc(pillX + pillW - 25, pillY + pillH/2, 3, 0, Math.PI*2);
                ctx.fill();

                ctx.restore();

                // 8. Simulated Cursor Overlay
                if (state.feedState !== 'swiping') {
                    ctx.shadowBlur = 10; ctx.shadowColor = 'rgba(0,0,0,0.5)';
                    ctx.fillStyle = '#fff';
                    // Arrow cursor
                    ctx.beginPath();
                    ctx.moveTo(state.cursor.x, state.cursor.y);
                    ctx.lineTo(state.cursor.x + 12, state.cursor.y + 12);
                    ctx.lineTo(state.cursor.x + 5, state.cursor.y + 12);
                    ctx.lineTo(state.cursor.x, state.cursor.y + 18);
                    ctx.closePath();
                    ctx.fill();

                    // Click Ripple
                    if (state.cursor.clicking) {
                        ctx.strokeStyle = 'rgba(255,255,255,0.8)';
                        ctx.lineWidth = 2;
                        ctx.beginPath(); ctx.arc(state.cursor.x, state.cursor.y, 20, 0, Math.PI*2); ctx.stroke();
                    }
                    ctx.shadowBlur = 0;
                }
            }
            // ... (Existing logic for other modes)
            else if (mode === 'search') {
                const processLine = w * 0.4;
                const laneCount = 5;
                const laneHeight = h / laneCount;

                ctx.lineWidth = 1;
                ctx.strokeStyle = 'rgba(255, 255, 255, 0.08)';
                for(let i=0; i<laneCount; i++) {
                    const ly = i * laneHeight + laneHeight/2;
                    ctx.beginPath(); ctx.moveTo(processLine, ly); ctx.lineTo(w, ly); ctx.stroke();
                }

                const scannerGlow = ctx.createLinearGradient(processLine, 0, processLine + 60, 0);
                scannerGlow.addColorStop(0, color);
                scannerGlow.addColorStop(1, 'transparent');
                ctx.fillStyle = scannerGlow;
                ctx.globalAlpha = 0.15;
                ctx.fillRect(processLine, 0, 60, h);

                ctx.fillStyle = color;
                ctx.globalAlpha = 0.8;
                ctx.fillRect(processLine, 0, 2, h);

                state.particles.forEach((p: any) => {
                    p.x += p.vx;
                    if (p.x < processLine) {
                        p.y += p.vy;
                        if (p.y < 0) p.y += h;
                        if (p.y > h) p.y -= h;
                        ctx.fillStyle = 'rgba(255, 255, 255, 0.4)';
                        ctx.globalAlpha = 0.6;
                        ctx.beginPath(); ctx.arc(p.x, p.y, p.size * 2, 0, Math.PI*2); ctx.fill();
                    } else {
                        const targetY = p.targetLane * laneHeight + laneHeight/2;
                        p.y += (targetY - p.y) * 0.15; 
                        p.x += 1.5; 
                        ctx.fillStyle = color;
                        ctx.globalAlpha = 1;
                        const packetWidth = 20 * p.size;
                        const packetHeight = 4;
                        ctx.shadowColor = color; ctx.shadowBlur = 10;
                        ctx.fillRect(p.x, p.y - packetHeight/2, packetWidth, packetHeight);
                        ctx.shadowBlur = 0;
                    }
                    if (p.x > w + 50) {
                        p.x = -20;
                        p.y = Math.random() * h;
                        p.vx = 2 + Math.random() * 1.5;
                        p.targetLane = Math.floor(Math.random() * laneCount);
                    }
                });
            }
            else if (mode === 'redaction') {
                const scanY = (time * 100) % (h + 100) - 50;
                state.particles.forEach((p: any) => {
                    const dist = Math.abs(p.y - scanY);
                    if (dist < 50) {
                        ctx.fillStyle = color;
                        ctx.globalAlpha = 1 - (dist/50);
                        ctx.fillRect(p.x, p.y, p.w, p.h);
                    } else {
                        ctx.fillStyle = 'rgba(255,255,255,0.05)';
                        ctx.globalAlpha = 1;
                        ctx.fillRect(p.x, p.y, p.w, p.h);
                    }
                });
                ctx.fillStyle = '#fff';
                ctx.fillRect(0, scanY, w, 2);
            }
            else if (mode === 'logic') {
                // Spawn Packets
                if (Math.random() > 0.98) {
                    const startNodes = state.nodes.filter((n: any) => n.type === 'trigger');
                    const start = startNodes[Math.floor(Math.random() * startNodes.length)];
                    state.nodes.forEach((n: any) => { if(n.id === start.id) n.active = 1.0; });

                    // Find links from this start
                    const links = state.links.filter((l: any) => l.from === start.id);
                    links.forEach((l: any) => {
                        state.packets.push({
                            fromId: l.from, toId: l.to, progress: 0, speed: 0.02 + Math.random() * 0.01
                        });
                    });
                }

                // Draw Links
                ctx.lineWidth = 2;
                state.links.forEach((l: any) => {
                    const n1 = state.nodes.find((n: any) => n.id === l.from);
                    const n2 = state.nodes.find((n: any) => n.id === l.to);

                    const grad = ctx.createLinearGradient(n1.x, n1.y, n2.x, n2.y);
                    grad.addColorStop(0, 'rgba(255,255,255,0.1)');
                    grad.addColorStop(1, 'rgba(255,255,255,0.05)');
                    ctx.strokeStyle = grad;

                    ctx.beginPath();
                    ctx.moveTo(n1.x, n1.y);
                    const midX = (n1.x + n2.x) / 2;
                    ctx.bezierCurveTo(midX, n1.y, midX, n2.y, n2.x, n2.y);
                    ctx.stroke();
                });

                // Draw Packets
                for (let i = state.packets.length - 1; i >= 0; i--) {
                    const p = state.packets[i];
                    p.progress += p.speed;

                    const n1 = state.nodes.find((n: any) => n.id === p.fromId);
                    const n2 = state.nodes.find((n: any) => n.id === p.toId);

                    const midX = (n1.x + n2.x) / 2;
                    const t = p.progress;
                    const invT = 1 - t;

                    const x = invT*invT*invT*n1.x + 3*invT*invT*t*midX + 3*invT*t*t*midX + t*t*t*n2.x;
                    const y = invT*invT*invT*n1.y + 3*invT*invT*t*n1.y + 3*invT*t*t*n2.y + t*t*t*n2.y;

                    ctx.fillStyle = color;
                    ctx.shadowBlur = 10; ctx.shadowColor = color;
                    ctx.beginPath(); ctx.arc(x, y, 3, 0, Math.PI*2); ctx.fill();
                    ctx.shadowBlur = 0;

                    if (p.progress >= 1) {
                        n2.active = 1.0;
                        const nextLinks = state.links.filter((l: any) => l.from === n2.id);
                        nextLinks.forEach((l: any) => {
                            state.packets.push({ fromId: l.from, toId: l.to, progress: 0, speed: 0.02 });
                        });
                        state.packets.splice(i, 1);
                    }
                }

                // Draw Nodes
                state.nodes.forEach((n: any) => {
                    const isActive = n.active > 0.01;
                    if (n.active > 0) n.active *= 0.95;

                    ctx.save();
                    ctx.translate(n.x, n.y);

                    if (n.type === 'trigger') {
                        ctx.fillStyle = isActive ? color : '#1a1a1c';
                        ctx.strokeStyle = isActive ? '#fff' : 'rgba(255,255,255,0.2)';
                        ctx.beginPath(); ctx.moveTo(0, -20); ctx.lineTo(20, 0); ctx.lineTo(0, 20); ctx.lineTo(-20, 0); ctx.closePath();
                    } else if (n.type === 'process') {
                        ctx.fillStyle = isActive ? color : '#1a1a1c';
                        ctx.strokeStyle = isActive ? '#fff' : 'rgba(255,255,255,0.2)';
                        ctx.beginPath(); ctx.roundRect(-40, -20, 80, 40, 4);
                    } else {
                        ctx.fillStyle = isActive ? color : '#1a1a1c';
                        ctx.strokeStyle = isActive ? '#fff' : 'rgba(255,255,255,0.2)';
                        ctx.beginPath(); ctx.roundRect(-30, -15, 60, 30, 15);
                    }

                    ctx.globalAlpha = isActive ? 0.8 : 0.5;
                    ctx.fill();
                    ctx.globalAlpha = 1;
                    ctx.lineWidth = 1;
                    ctx.stroke();

                    ctx.fillStyle = '#fff';
                    ctx.font = '9px monospace';
                    ctx.textAlign = 'center';
                    ctx.textBaseline = 'middle';

                    const textW = ctx.measureText(n.label).width;
                    ctx.fillStyle = 'rgba(0,0,0,0.6)';
                    ctx.fillRect(-textW/2 - 4, 22, textW + 8, 14);
                    ctx.fillStyle = isActive ? color : '#888';
                    ctx.fillText(n.label, 0, 29);

                    ctx.restore();
                });
            }
            // ... (Other modes omitted for brevity, logic remains in 'render')
        };

        const observer = new ResizeObserver(() => { resize(); });
        observer.observe(container);
        resize();
        render();

        return () => {
            observer.disconnect();
            cancelAnimationFrame(frameId);
        };
    }, [mode, color]);

    return (
        <div ref={containerRef} className="w-full h-full relative overflow-hidden bg-[#0c0c0e]">
            <canvas ref={canvasRef} className="block absolute top-0 left-0" />
            <div className="absolute inset-0 pointer-events-none opacity-20" style={{ backgroundImage: 'linear-gradient(rgba(18, 16, 16, 0) 50%, rgba(0, 0, 0, 0.25) 50%), linear-gradient(90deg, rgba(255, 0, 0, 0.06), rgba(0, 255, 0, 0.02), rgba(0, 0, 255, 0.06))', backgroundSize: '100% 2px, 3px 100%' }} />
        </div>
    );
};
